package com.modernmmopm.util;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.awt.Color;
import java.util.List;
import org.junit.Test;

public class PmMessageFormatterTest
{
	@Test
	public void parsesImageTagAsChatIconRun()
	{
		final List<PmMessageFormatter.StyledRun> runs = PmMessageFormatter.parseRuns("<img=415>x3", Color.WHITE);

		assertEquals(2, runs.size());
		assertTrue(runs.get(0).isChatIcon());
		assertEquals(415, runs.get(0).getChatIconId());
		assertEquals("<img=415>", runs.get(0).getText());
		assertEquals("x3", runs.get(1).getText());
	}

	@Test
	public void preservesColorAroundImageTag()
	{
		final Color red = new Color(0xFF0000);
		final List<PmMessageFormatter.StyledRun> runs = PmMessageFormatter.parseRuns(
			"a <col=ff0000><img=415>x3</col>", Color.WHITE);

		assertEquals(3, runs.size());
		assertEquals(Color.WHITE, runs.get(0).getColor());
		assertEquals(red, runs.get(1).getColor());
		assertEquals(red, runs.get(2).getColor());
		assertTrue(runs.get(1).isChatIcon());
		assertFalse(runs.get(2).isChatIcon());
	}

	@Test
	public void parsesRuneLiteNamedColorTags()
	{
		final Color normal = new Color(0xDDEEFF);
		final List<PmMessageFormatter.StyledRun> runs = PmMessageFormatter.parseRuns(
			"<colHIGHLIGHT>Layout: <colNORMAL>Thieving, Guardians", normal);

		assertEquals(2, runs.size());
		assertEquals("Layout: ", runs.get(0).getText());
		assertEquals(new Color(0xFFFF00), runs.get(0).getColor());
		assertEquals("Thieving, Guardians", runs.get(1).getText());
		assertEquals(normal, runs.get(1).getColor());
	}

	@Test
	public void escapedImageTagStaysLiteralText()
	{
		final List<PmMessageFormatter.StyledRun> runs = PmMessageFormatter.parseRuns("<lt>img=415<gt>", Color.WHITE);

		assertEquals(1, runs.size());
		assertFalse(runs.get(0).isChatIcon());
		assertEquals("<img=415>", runs.get(0).getText());
	}

	@Test
	public void unknownTagStaysLiteralText()
	{
		final List<PmMessageFormatter.StyledRun> runs = PmMessageFormatter.parseRuns("<foo=1>", Color.WHITE);

		assertEquals(1, runs.size());
		assertFalse(runs.get(0).isChatIcon());
		assertEquals("<foo=1>", runs.get(0).getText());
	}
}

package com.modernmmopm.model;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.api.MessageNode;

public class Conversation
{
	private static final int MAX_HISTORY = 250;

	private final String cleanedName;
	private String displayName;

	private int unreadCount;
	private int scrollOffset;
	private long flashUntilMillis;
	private AccountBadge accountBadge;

	private final List<ConversationMessage> messages = new ArrayList<>();

	public Conversation(String cleanedName, String displayName)
	{
		this.cleanedName = cleanedName;
		this.displayName = displayName;
	}

	public String getCleanedName()
	{
		return cleanedName;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public void setDisplayName(String displayName)
	{
		this.displayName = displayName;
	}

	public int getUnreadCount()
	{
		return unreadCount;
	}

	public void setUnreadCount(int unreadCount)
	{
		this.unreadCount = unreadCount;
	}

	public int getScrollOffset()
	{
		return scrollOffset;
	}

	public void setScrollOffset(int scrollOffset)
	{
		this.scrollOffset = scrollOffset;
	}

	public long getFlashUntilMillis()
	{
		return flashUntilMillis;
	}

	public void setFlashUntilMillis(long flashUntilMillis)
	{
		this.flashUntilMillis = flashUntilMillis;
	}

	public AccountBadge getAccountBadge()
	{
		return accountBadge;
	}

	public void setAccountBadge(AccountBadge accountBadge)
	{
		this.accountBadge = accountBadge;
	}

	public void addMessage(boolean incoming, String text, MessageNode messageNode)
	{
		messages.add(new ConversationMessage(incoming, text, text, Instant.now(), messageNode));
		if (messages.size() > MAX_HISTORY)
		{
			messages.remove(0);
		}
	}

	public List<ConversationMessage> getMessagesView()
	{
		return Collections.unmodifiableList(messages);
	}
}

package com.modernmmopm.model;

import java.util.Set;

/**
 * High-level OSRS world region grouping used for friends-list rendering.
 * The {@link #fromWorld(int, int)} resolver maps a world ID + RuneLite location ID
 * onto one of these regions so the panel can show a flag and short code per friend.
 */
public enum WorldRegion
{
	US_EAST("East"),
	US_WEST("West"),
	US("US"),
	GB("GB"),
	AU("AU"),
	DE("DE"),
	BR("BR");

	// World IDs sourced from the OSRS wiki world list. Worlds not in either set
	// fall back to a generic US flag/code via {@link #US}.
	private static final Set<Integer> US_EAST_WORLDS = Set.of(
		301, 305, 314, 321, 322, 329, 330, 337, 345, 346, 353, 354, 361, 362, 369, 370,
		377, 385, 386, 393, 394, 402, 403, 404, 415, 416, 417, 467, 468, 469, 470, 471,
		472, 473, 474, 475, 476, 477, 478, 479, 480, 481, 482, 483, 484, 485, 486, 487,
		488, 489, 490, 491, 492, 493, 494, 495, 496, 539, 573, 574, 575, 576, 578, 579,
		580, 581, 596, 597, 598, 609, 610, 611, 612, 613, 614, 615, 616, 617, 618);

	private static final Set<Integer> US_WEST_WORLDS = Set.of(
		306, 307, 313, 315, 319, 320, 323, 324, 331, 332, 338, 339, 340, 347, 348, 355,
		356, 357, 374, 378, 409, 410, 411, 418, 419, 420, 421, 422, 423, 428, 429, 430,
		431, 432, 433, 434, 435, 436, 437, 438, 439, 440, 441, 442, 443, 444, 445, 446,
		538, 540, 541, 542, 543, 544, 545, 546, 547, 599, 600, 601, 602, 603, 604, 606,
		607, 608);

	private static final Set<Integer> BRAZIL_WORLDS = Set.of(
		692, 693, 694, 695, 696, 697);

	private final String code;

	WorldRegion(String code)
	{
		this.code = code;
	}

	public String getCode()
	{
		return code;
	}

	/**
	 * Resolve a region from a world ID + RuneLite WorldResult location code.
	 * Location 0 is treated as US and refined to East/West using known world ID lists.
	 *
	 * @param worldId the OSRS world id (e.g. 301)
	 * @param locationId the RuneLite {@code World#getLocation()} code
	 * @return the matched region, or {@code null} if the location is unknown
	 */
	public static WorldRegion fromWorld(int worldId, int locationId)
	{
		if (BRAZIL_WORLDS.contains(worldId))
		{
			return BR;
		}

		switch (locationId)
		{
			case 0:
				if (worldId > 0)
				{
					if (US_EAST_WORLDS.contains(worldId))
					{
						return US_EAST;
					}
					if (US_WEST_WORLDS.contains(worldId))
					{
						return US_WEST;
					}
				}
				return US;
			case 1:
				return GB;
			case 3:
				return AU;
			case 7:
				return DE;
			default:
				return null;
		}
	}
}

package com.modernmmopm.model;

/**
 * One row in the friends roster. {@code world == 0} means offline (OSRS client convention).
 */
public final class FriendListEntry
{
	private final int rowIndex;
	private final String displayName;
	private final int world;
	private final boolean sameWorldAsLocal;
	private final WorldRegion worldRegion;
	private final boolean bestFriend;

	public FriendListEntry(int rowIndex, String displayName, int world, boolean sameWorldAsLocal, WorldRegion worldRegion, boolean bestFriend)
	{
		this.rowIndex = rowIndex;
		this.displayName = displayName;
		this.world = world;
		this.sameWorldAsLocal = sameWorldAsLocal;
		this.worldRegion = worldRegion;
		this.bestFriend = bestFriend;
	}

	public int getRowIndex()
	{
		return rowIndex;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public int getWorld()
	{
		return world;
	}

	public boolean isSameWorldAsLocal()
	{
		return sameWorldAsLocal;
	}

	public WorldRegion getWorldRegion()
	{
		return worldRegion;
	}

	public boolean isBestFriend()
	{
		return bestFriend;
	}

	public boolean isOffline()
	{
		return world == 0;
	}
}

package com.modernmmopm.model;

import net.runelite.api.IconID;

public enum AccountBadge
{
	IRONMAN(IconID.IRONMAN.getIndex(), "Ironman_chat_badge.png"),
	ULTIMATE_IRONMAN(IconID.ULTIMATE_IRONMAN.getIndex(), "Ultimate_ironman_chat_badge.png"),
	HARDCORE_IRONMAN(IconID.HARDCORE_IRONMAN.getIndex(), "Hardcore_Ironman.png"),
	GROUP_IRONMAN(IconID.GROUP_IRONMAN.getIndex(), "Group_ironman_chat_badge.png"),
	HARDCORE_GROUP_IRONMAN(IconID.HARDCORE_GROUP_IRONMAN.getIndex(), "Hardcore_group_ironman_chat_badge.png"),
	UNRANKED_GROUP_IRONMAN(IconID.UNRANKED_GROUP_IRONMAN.getIndex(), "Unranked_group_ironman_chat_badge.png");

	private final int iconId;
	private final String iconFileName;

	AccountBadge(int iconId, String iconFileName)
	{
		this.iconId = iconId;
		this.iconFileName = iconFileName;
	}

	public String getIconFileName()
	{
		return iconFileName;
	}

	public static AccountBadge fromIconId(int iconId)
	{
		for (AccountBadge badge : values())
		{
			if (badge.iconId == iconId)
			{
				return badge;
			}
		}
		return null;
	}
}

package com.modernmmopm.model;

