	{
		this.incoming = incoming;
		this.originalText = originalText;
		this.text = text;
		this.timestamp = timestamp;
		this.messageNode = messageNode;
		this.liveSyncEnabled = messageNode != null;
	}

	public boolean isIncoming()
	{
		return incoming;
	}

	public String getOriginalText()
	{
		return originalText;
	}

	public String getText()
	{
		return text;
	}

	public void setText(String text)
	{
		this.text = text;
	}

	public Instant getTimestamp()
	{
		return timestamp;
	}

	public MessageNode getMessageNode()
	{
		return messageNode;
	}

	public boolean isLiveSyncEnabled()
	{
		return liveSyncEnabled;
	}

	public void setLiveSyncEnabled(boolean liveSyncEnabled)
	{
		this.liveSyncEnabled = liveSyncEnabled;
	}
}

package com.modernmmopm;

import com.google.inject.Provides;
