@PluginDescriptor(
	name = "Modern MMO PM",
	description = "Modern MMO-style private messaging panel overlay",
	tags = {"chat", "pm", "private", "message", "overlay", "whisper"}
)
public class ModernMmoPmPlugin extends Plugin
{
	/** Scrollbar / wheel map key for the friends roster (not a conversation tab). */
	public static final String FRIENDS_SCROLL_KEY = "__modernmmopm_friends_scroll__";

	private static final int MAX_DEDUPE_KEYS = 250;
	private static final long DEDUPE_WINDOW_MS = 1800L;
	private static final long FLASH_DURATION_MS = 2400L;
	private static final String BEST_FRIENDS_CONFIG_PREFIX = "bestFriends.";
	private static final Pattern CHAT_ICON_PATTERN = Pattern.compile("<img=(\\d+)>", Pattern.CASE_INSENSITIVE);

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ModernMmoPmOverlay overlay;

	@Inject
	private ModernMmoPmConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private WorldService worldService;

	private final LinkedHashMap<String, Conversation> conversations = new LinkedHashMap<>();
	private final LinkedHashMap<String, Long> recentMessageKeys = new LinkedHashMap<>();

	private boolean minimized;
	private String hoveredConversationKey;
	private String activeConversationKey;
	private String historyOwnerKey;
	private boolean pendingAccountBinding;
	private boolean friendsViewActive;
	private final List<FriendListEntry> friendEntriesSnapshot = new ArrayList<>();
	private final Set<String> bestFriendKeys = new LinkedHashSet<>();
	private int streamerShuffleSeed;

	private final KeyListener overlayToggleHotkey = new KeyListener()
	{
		@Override
		public void keyPressed(KeyEvent e)
		{
			final Keybind hotkey = config.overlayToggleHotkey();
			if (hotkey == null || hotkey == Keybind.NOT_SET || !hotkey.matches(e))
			{
				return;
			}

			toggleMinimized();
			overlay.revalidate();
			e.consume();
		}

		@Override
		public void keyReleased(KeyEvent e)
		{
		}

		@Override
		public void keyTyped(KeyEvent e)
		{
		}
	};

	@Override
	protected void startUp()
	{
		minimized = true;
		pendingAccountBinding = client.getGameState() == GameState.LOGGED_IN;
		overlayManager.add(overlay);
		mouseManager.registerMouseListener(overlay);
		mouseManager.registerMouseWheelListener(overlay);
		keyManager.registerKeyListener(overlayToggleHotkey);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		mouseManager.unregisterMouseListener(overlay);
		mouseManager.unregisterMouseWheelListener(overlay);
		keyManager.unregisterKeyListener(overlayToggleHotkey);
		clearAllState();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		final ChatMessageType type = event.getType();
		if (type != ChatMessageType.PRIVATECHAT && type != ChatMessageType.PRIVATECHATOUT)
		{
			return;
		}

		final boolean incoming = type == ChatMessageType.PRIVATECHAT;
		final String rawName = coalesceName(event.getName(), event.getSender());
		final String displayName = NameSanitizer.displayName(rawName);
		final AccountBadge accountBadge = resolveAccountBadge(event.getName(), event.getSender());
		final String message = normalizeMessage(event.getMessage());
		final String visibleMessage = PmMessageFormatter.visibleText(message);
		if (displayName.isEmpty() || visibleMessage.isEmpty())
		{
			return;
		}

		if (isDuplicate(incoming, displayName, visibleMessage))
		{
			return;
		}

		final Conversation conversation = upsertConversation(displayName);
		if (conversation == null)
		{
			return;
		}

		if (accountBadge != null)
		{
			conversation.setAccountBadge(accountBadge);
		}
		conversation.addMessage(incoming, message, event.getMessageNode());

		if (incoming)
		{
			onIncomingMessage(conversation);
		}
		else
		{
			setActiveConversation(conversation.getCleanedName(), config.expandPanelOnOutgoingPm());
			conversation.setFlashUntilMillis(0L);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState gameState = event.getGameState();
		if (gameState == GameState.LOGGED_IN)
		{
			pendingAccountBinding = true;
			return;
		}

		clearTransientState();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (pendingAccountBinding && !bindHistoryToCurrentAccount())
		{
			return;
		}

		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			return;
		}

		refreshFriendSnapshot();

		boolean changed = false;
		for (Conversation conversation : conversations.values())
		{
			for (ConversationMessage message : conversation.getMessagesView())
			{
				final String syncedText = syncMessageText(message);
				if (!syncedText.equals(message.getText()))
				{
					message.setText(syncedText);
					changed = true;
				}
			}
		}

		if (changed)
		{
			overlay.revalidate();
		}
	}

	public List<Conversation> getConversationsInOrder()
	{
		return List.copyOf(conversations.values());
	}

	public boolean isMinimized()
	{
		return minimized;
	}

	public ModernMmoPmConfig getConfig()
	{
		return config;
	}

	public String getActiveConversationKey()
	{
		return activeConversationKey;
	}

	public String getHoveredConversationKey()
	{
		return hoveredConversationKey;
	}

	public Conversation getActiveConversation()
	{
		return activeConversationKey == null ? null : conversations.get(activeConversationKey);
	}

	public Conversation getConversation(String conversationKey)
	{
		return conversations.get(conversationKey);
	}

	public int getTotalUnreadCount()
	{
		int totalUnread = 0;
		for (Conversation conversation : conversations.values())
		{
			totalUnread += Math.max(0, conversation.getUnreadCount());
		}
		return totalUnread;
	}

	/**
	 * Friends roster is shown when there are no open PM tabs or the user explicitly opened Friends.
	 */
	public boolean showFriendsRoster()
	{
		return conversations.isEmpty() || friendsViewActive;
	}

	public void setFriendsViewActive(boolean active)
	{
		this.friendsViewActive = active;
	}

	public boolean isBestFriend(String displayName)
	{
		return isBestFriendKey(NameSanitizer.cleanedKey(displayName));
	}

	public boolean isBestFriendKey(String cleanedKey)
	{
		return cleanedKey != null && bestFriendKeys.contains(cleanedKey);
	}

	public void toggleBestFriend(String conversationKey)
	{
		if (conversationKey == null || conversationKey.trim().isEmpty())
		{
			return;
		}

		final String cleanedKey = NameSanitizer.cleanedKey(conversationKey);
		if (cleanedKey.isEmpty())
		{
			return;
		}

		if (!bestFriendKeys.add(cleanedKey))
		{
			bestFriendKeys.remove(cleanedKey);
		}

		saveBestFriends();
		// refreshFriendSnapshot reads client.getFriendContainer(), which must run on the
		// client thread. This entry point is invoked from the AWT mouse listener.
		clientThread.invoke(() ->
		{
			refreshFriendSnapshot();
			overlay.revalidate();
		});
	}

	public List<FriendListEntry> getFriendsSnapshot()
	{
		return Collections.unmodifiableList(friendEntriesSnapshot);
	}

	public void openPrivateMessageToFriend(String displayName)
	{
		if (displayName == null || displayName.trim().isEmpty())
		{
			return;
		}

		final Conversation conversation = upsertConversation(displayName.trim());
		if (conversation == null)
		{
			return;
		}

		friendsViewActive = false;
		setActiveConversation(conversation.getCleanedName(), true);
	}

	public void setHoveredConversationKey(String conversationKey)
	{
		this.hoveredConversationKey = conversationKey;
	}

	public void setActiveConversation(String conversationKey)
	{
		setActiveConversation(conversationKey, true);
	}

	public void setActiveConversation(String conversationKey, boolean expandPanel)
	{
		final Conversation conversation = conversations.get(conversationKey);
		if (conversation == null)
		{
			return;
		}

		friendsViewActive = false;
		conversation.setUnreadCount(0);
		conversation.setFlashUntilMillis(0L);
		activeConversationKey = conversationKey;
		if (expandPanel)
		{
			minimized = false;
		}
	}

	public void toggleMinimized()
	{
		minimized = !minimized;
		if (!minimized)
		{
			clearVisibleActiveUnread();
		}
	}

	public void setMinimized(boolean minimized)
	{
		this.minimized = minimized;
		if (!minimized)
		{
			clearVisibleActiveUnread();
		}
	}

	public void closeConversation(String conversationKey)
	{
		if (conversationKey == null)
		{
			return;
		}

		final boolean wasActiveConversation = conversationKey.equals(activeConversationKey);
		conversations.remove(conversationKey);
		if (conversationKey.equals(hoveredConversationKey))
		{
			hoveredConversationKey = null;
		}
		if (wasActiveConversation)
		{
			activeConversationKey = conversations.isEmpty() ? null : conversations.keySet().iterator().next();
			friendsViewActive = true;
		}
		else if (conversations.isEmpty())
		{
			friendsViewActive = true;
		}
	}

	public void closeHoveredConversation()
	{
		if (hoveredConversationKey != null)
		{
			closeConversation(hoveredConversationKey);
		}
	}

	public void openPmInputForActiveConversation()
	{
		final Conversation conversation = getActiveConversation();
		if (conversation == null)
		{
			return;
		}

		final String target = conversation.getDisplayName();
		if (target == null || target.trim().isEmpty())
		{
			return;
		}

		clientThread.invoke(() -> client.runScript(ScriptID.OPEN_PRIVATE_MESSAGE_INTERFACE, target));
	}

	private void onIncomingMessage(Conversation conversation)
	{
		final boolean isActive = conversation.getCleanedName().equals(activeConversationKey) && !showFriendsRoster();
		if (isActive && !minimized)
		{
			conversation.setUnreadCount(0);
			conversation.setFlashUntilMillis(0L);
			return;
		}

		conversation.setUnreadCount(conversation.getUnreadCount() + 1);
		conversation.setFlashUntilMillis(Instant.now().toEpochMilli() + FLASH_DURATION_MS);
	}

	private void clearVisibleActiveUnread()
	{
		if (showFriendsRoster())
		{
			return;
		}

		final Conversation conversation = getActiveConversation();
		if (conversation == null)
		{
			return;
		}

		conversation.setUnreadCount(0);
		conversation.setFlashUntilMillis(0L);
	}

	private Conversation upsertConversation(String displayName)
	{
		final String key = NameSanitizer.cleanedKey(displayName);
		if (key.isEmpty())
		{
			return null;
		}

		Conversation conversation = conversations.get(key);
		if (conversation != null)
		{
			conversation.setDisplayName(displayName);
			return conversation;
		}

		final boolean wasEmpty = conversations.isEmpty();
		conversation = new Conversation(key, displayName);
		conversations.put(key, conversation);
		if (wasEmpty)
		{
			friendsViewActive = false;
		}
		if (activeConversationKey == null)
		{
			activeConversationKey = key;
			conversation.setUnreadCount(0);
		}
		return conversation;
	}

	private boolean isDuplicate(boolean incoming, String sender, String message)
	{
		final long now = Instant.now().toEpochMilli();
		final String dedupeKey = (incoming ? "in|" : "out|")
			+ sender.toLowerCase(Locale.ROOT) + "|" + message.toLowerCase(Locale.ROOT);
		final Long lastSeen = recentMessageKeys.get(dedupeKey);
		if (lastSeen != null && now - lastSeen < DEDUPE_WINDOW_MS)
		{
			return true;
		}

		recentMessageKeys.put(dedupeKey, now);
		while (recentMessageKeys.size() > MAX_DEDUPE_KEYS)
		{
			final String firstKey = recentMessageKeys.keySet().iterator().next();
			recentMessageKeys.remove(firstKey);
		}

		return false;
	}

	/**
	 * Order matches {@link FriendContainer#getMembers()} iteration (client friends list order).
	 */
	private void refreshFriendSnapshot()
	{
		friendEntriesSnapshot.clear();
		final FriendContainer friendContainer = client.getFriendContainer();
		if (friendContainer == null)
		{
			return;
		}

		final Friend[] members = friendContainer.getMembers();
		if (members == null)
		{
			return;
		}

		final int localWorld = client.getWorld();
		final WorldResult worldResult = worldService.getWorlds();
		final List<FriendListEntry> working = new ArrayList<>();
		for (Friend friend : members)
		{
			if (friend == null)
			{
				continue;
			}

			final String display = NameSanitizer.displayName(friend.getName());
			if (display.isEmpty())
			{
				continue;
			}

			final String cleanedKey = NameSanitizer.cleanedKey(display);
			final int world = friend.getWorld();
			final boolean sameWorld = world != 0 && world == localWorld;
			final boolean bestFriend = bestFriendKeys.contains(cleanedKey);
			working.add(new FriendListEntry(-1, display, world, sameWorld, resolveWorldRegion(worldResult, world), bestFriend));
		}

		final boolean streamerMode = config.streamerMode();
		if (streamerMode)
		{
			if (streamerShuffleSeed == 0)
			{
				int seed = ThreadLocalRandom.current().nextInt();
				streamerShuffleSeed = seed == 0 ? 1 : seed;
			}
		}
		else
		{
			streamerShuffleSeed = 0;
		}

		final Comparator<FriendListEntry> base = Comparator
			.comparingInt((FriendListEntry e) -> e.isOffline() ? 1 : 0)
			.thenComparingInt(e -> e.isBestFriend() ? 0 : 1);
		final Comparator<FriendListEntry> rank;
		if (streamerMode)
		{
			final int seed = streamerShuffleSeed;
			rank = base.thenComparingInt(e -> e.isBestFriend() ? 0 : shuffleHash(e.getDisplayName(), seed));
		}
		else
		{
			rank = base
				.thenComparingInt(e -> e.isOffline() || !e.isSameWorldAsLocal() ? 1 : 0)
				.thenComparingInt(e -> e.isOffline() ? 0 : e.getWorld());
		}
		working.sort(rank.thenComparing(FriendListEntry::getDisplayName, String.CASE_INSENSITIVE_ORDER));

		for (int i = 0; i < working.size(); i++)
		{
			final FriendListEntry src = working.get(i);
			friendEntriesSnapshot.add(new FriendListEntry(i, src.getDisplayName(), src.getWorld(), src.isSameWorldAsLocal(), src.getWorldRegion(), src.isBestFriend()));
		}
	}

	/**
	 * Stable, name-and-seed-derived ordering hash used for streamer-mode shuffling.
	 * Same name+seed always yields the same int, so the shuffle persists across re-renders
	 * but resets to a fresh permutation whenever streamer mode is re-enabled.
	 */
	private static int shuffleHash(String name, int seed)
	{
		if (name == null)
		{
			return seed;
		}

		int hash = seed;
		for (int i = 0; i < name.length(); i++)
		{
			hash = 31 * hash + Character.toLowerCase(name.charAt(i));
		}
		return hash;
	}

	private static WorldRegion resolveWorldRegion(WorldResult worldResult, int worldId)
	{
		if (worldResult == null || worldId <= 0)
		{
			return null;
		}

		final World world = worldResult.findWorld(worldId);
		return world == null ? null : WorldRegion.fromWorld(worldId, world.getLocation());
	}

	private boolean bindHistoryToCurrentAccount()
	{
		final String currentAccountKey = resolveCurrentAccountKey();
		if (currentAccountKey.isEmpty())
		{
			return false;
		}

		pendingAccountBinding = false;
		if (historyOwnerKey == null)
		{
			historyOwnerKey = currentAccountKey;
			loadBestFriends(currentAccountKey);
			return true;
		}

		if (!historyOwnerKey.equals(currentAccountKey))
		{
			clearConversationHistory();
			historyOwnerKey = currentAccountKey;
			loadBestFriends(currentAccountKey);
			overlay.revalidate();
		}

		return true;
	}

	private void loadBestFriends(String accountKey)
	{
		bestFriendKeys.clear();
		if (accountKey == null || accountKey.isEmpty())
		{
			return;
		}

		final String serialized = configManager.getConfiguration(ModernMmoPmConfig.GROUP, BEST_FRIENDS_CONFIG_PREFIX + accountKey);
		if (serialized == null || serialized.trim().isEmpty())
		{
			return;
		}

		for (String part : serialized.split(","))
		{
			final String cleaned = NameSanitizer.cleanedKey(part);
			if (!cleaned.isEmpty())
			{
				bestFriendKeys.add(cleaned);
			}
		}
	}

	private void saveBestFriends()
	{
		final String accountKey = historyOwnerKey == null || historyOwnerKey.isEmpty() ? resolveCurrentAccountKey() : historyOwnerKey;
		if (accountKey == null || accountKey.isEmpty())
		{
			return;
		}

		final List<String> ordered = new ArrayList<>(bestFriendKeys);
		Collections.sort(ordered);
		configManager.setConfiguration(ModernMmoPmConfig.GROUP, BEST_FRIENDS_CONFIG_PREFIX + accountKey, String.join(",", ordered));
	}

	private void clearTransientState()
	{
		recentMessageKeys.clear();
		hoveredConversationKey = null;
		friendsViewActive = false;
		friendEntriesSnapshot.clear();
		disableLiveMessageSync();
	}

	private void clearConversationHistory()
	{
		conversations.clear();
		activeConversationKey = null;
		hoveredConversationKey = null;
		friendsViewActive = false;
		minimized = true;
	}

	private void clearAllState()
	{
		clearTransientState();
		clearConversationHistory();
		bestFriendKeys.clear();
		historyOwnerKey = null;
		pendingAccountBinding = false;
	}

	private void disableLiveMessageSync()
	{
		for (Conversation conversation : conversations.values())
		{
			for (ConversationMessage message : conversation.getMessagesView())
			{
				message.setLiveSyncEnabled(false);
			}
		}
	}

	private String resolveCurrentAccountKey()
	{
		if (client.getLocalPlayer() == null)
		{
			return "";
		}

		return NameSanitizer.cleanedKey(client.getLocalPlayer().getName());
	}

	private static String coalesceName(String first, String second)
	{
		if (first != null && !first.trim().isEmpty())
		{
			return first;
		}
		return second == null ? "" : second;
	}

	private static AccountBadge resolveAccountBadge(String first, String second)
	{
		final AccountBadge firstBadge = parseAccountBadge(first);
		return firstBadge == null ? parseAccountBadge(second) : firstBadge;
	}

	private static AccountBadge parseAccountBadge(String rawName)
	{
		if (rawName == null || rawName.isEmpty())
		{
			return null;
		}

		final Matcher matcher = CHAT_ICON_PATTERN.matcher(rawName);
		while (matcher.find())
		{
			try
			{
				final AccountBadge badge = AccountBadge.fromIconId(Integer.parseInt(matcher.group(1)));
				if (badge != null)
				{
					return badge;
				}
			}
			catch (NumberFormatException ignored)
			{
				// Ignore malformed chat image tags and continue scanning.
			}
		}
		return null;
	}

	private static String normalizeMessage(String raw)
	{
		if (raw == null)
		{
			return "";
		}

		return raw.replace('\n', ' ').trim();
	}

	private static String syncMessageText(ConversationMessage conversationMessage)
	{
		if (!conversationMessage.isLiveSyncEnabled())
		{
			return conversationMessage.getText();
		}

		final MessageNode messageNode = conversationMessage.getMessageNode();
		if (messageNode == null)
		{
			conversationMessage.setLiveSyncEnabled(false);
			return conversationMessage.getText();
		}

		final String formatted = messageNode.getRuneLiteFormatMessage();
		if (formatted != null && !formatted.isEmpty())
		{
			final String normalized = normalizeMessage(formatted);
			if (!PmMessageFormatter.visibleText(normalized).isEmpty())
			{
				conversationMessage.setLiveSyncEnabled(false);
				return normalized;
			}
		}

		final String latestRaw = normalizeMessage(messageNode.getValue());
		if (shouldUseMessageNodeValue(conversationMessage.getOriginalText(), PmMessageFormatter.visibleText(latestRaw)))
		{
			conversationMessage.setLiveSyncEnabled(false);
			return latestRaw;
		}

		return conversationMessage.getText();
	}

	private static boolean shouldUseMessageNodeValue(String originalText, String latestVisible)
	{
		if (latestVisible == null || latestVisible.isEmpty())
		{
			return false;
		}

		final String originalVisible = PmMessageFormatter.visibleText(originalText);
		return originalVisible.startsWith("!") && !latestVisible.equals(originalVisible);
	}

	@Provides
	ModernMmoPmConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ModernMmoPmConfig.class);
	}
}

