	@Inject
	public ModernMmoPmOverlay(ModernMmoPmPlugin plugin, Client client)
	{
		super(plugin);
		this.plugin = plugin;
		this.client = client;
		setPriority(PRIORITY_HIGH);
		// UNDER_WIDGETS so the panel stacks with other UI overlays and shows snap corners while alt-dragging.
		setLayer(OverlayLayer.UNDER_WIDGETS);
		// Base anchor is bottom-left. preferredPosition/preferredLocation override this when the user
		// drags the panel; alt+right-click reset clears those and falls back to this position.
		setPosition(OverlayPosition.BOTTOM_LEFT);
		setMovable(true);
		setResizable(true);
		setSnappable(true);
		setPreferredSize(new Dimension(DEFAULT_WIDTH, DEFAULT_HEIGHT));
		setMinimumSize(MIN_WIDTH);

		addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Close tab", "Modern MMO PM", e -> plugin.closeHoveredConversation());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final Rectangle bounds = getBounds();
		final boolean collapsed = plugin.isMinimized();
		final List<Conversation> conversations = new ArrayList<>(plugin.getConversationsInOrder());

		final int currentWidth = bounds.width > 0 ? bounds.width : DEFAULT_WIDTH;
		final int currentHeight = bounds.height > 0 ? bounds.height : DEFAULT_HEIGHT;

		// Stash the most recent expanded dimensions so that toggling minimize doesn't
		// silently shrink the panel: when collapsed RuneLite persists the compact height,
		// and on the next un-minimize we'd otherwise clamp to MIN_EXPANDED_HEIGHT.
		if (!collapsed && currentHeight > COLLAPSED_HEIGHT)
		{
			lastExpandedHeight = clampDimension(currentHeight, MIN_EXPANDED_HEIGHT, MAX_EXPANDED_HEIGHT);
		}
		if (currentWidth >= MIN_WIDTH)
		{
			lastExpandedWidth = clampDimension(currentWidth, MIN_WIDTH, MAX_WIDTH);
		}

		final int width = clampDimension(collapsed ? lastExpandedWidth : currentWidth, MIN_WIDTH, MAX_WIDTH);
		final int expandedHeight = currentHeight > COLLAPSED_HEIGHT
			? clampDimension(currentHeight, MIN_EXPANDED_HEIGHT, MAX_EXPANDED_HEIGHT)
			: lastExpandedHeight;
		final int height = collapsed ? COLLAPSED_HEIGHT : expandedHeight;
		final int absX = bounds.x;
		final int absY = bounds.y;
		final HitboxState nextHitboxes = new HitboxState();
		if (!conversations.isEmpty() && !plugin.showFriendsRoster()
			&& (plugin.getActiveConversationKey() == null || plugin.getActiveConversation() == null))
		{
			plugin.setActiveConversation(conversations.get(0).getCleanedName());
		}

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		final Color base = applyAlpha(plugin.getConfig().chatboxColor(), plugin.getConfig().chatboxOpacity());

		if (collapsed)
		{
			drawCollapsedShell(graphics, width, absX, absY, plugin.getTotalUnreadCount(), nextHitboxes);
			applyHitboxState(nextHitboxes);
			return new Dimension(width, height);
		}

		drawExpandedShellBackground(graphics, width, height, base);

		final ModernMmoPmConfig.TabLocation tabLocation = plugin.getConfig().tabLocation();
		final Rectangle tabsRect;
		final Rectangle mainRect;
		switch (tabLocation)
		{
			case RIGHT:
				mainRect = new Rectangle(PANEL_PAD, PANEL_PAD, width - TAB_SIZE - (PANEL_PAD * 2) - 6, height - (PANEL_PAD * 2));
				tabsRect = new Rectangle(mainRect.x + mainRect.width + 6, PANEL_PAD, TAB_SIZE, height - (PANEL_PAD * 2));
				break;
			case TOP:
				tabsRect = new Rectangle(PANEL_PAD, PANEL_PAD, width - (PANEL_PAD * 2), ACTION_BAR_HEIGHT);
				mainRect = new Rectangle(PANEL_PAD, tabsRect.y + tabsRect.height + 6, width - (PANEL_PAD * 2), height - tabsRect.height - (PANEL_PAD * 2) - 6);
				break;
			case BOTTOM:
				mainRect = new Rectangle(PANEL_PAD, PANEL_PAD, width - (PANEL_PAD * 2), height - ACTION_BAR_HEIGHT - (PANEL_PAD * 2) - 6);
				tabsRect = new Rectangle(PANEL_PAD, mainRect.y + mainRect.height + 6, width - (PANEL_PAD * 2), ACTION_BAR_HEIGHT);
				break;
			case LEFT:
			default:
				tabsRect = new Rectangle(PANEL_PAD, PANEL_PAD, TAB_SIZE, height - (PANEL_PAD * 2));
				mainRect = new Rectangle(tabsRect.x + tabsRect.width + 6, PANEL_PAD, width - TAB_SIZE - (PANEL_PAD * 2) - 6, height - (PANEL_PAD * 2));
				break;
		}

		drawTabs(graphics, conversations, tabsRect, tabLocation, absX, absY, base, nextHitboxes);
		drawMainPanel(graphics, plugin.getActiveConversation(), mainRect, absX, absY, base, nextHitboxes);
		drawExpandedShellBorder(graphics, width, height);
		applyHitboxState(nextHitboxes);
		return new Dimension(width, height);
	}

	private void drawExpandedShellBackground(Graphics2D graphics, int width, int height, Color base)
	{
		graphics.setColor(shade(base, 0.86f, plugin.getConfig().chatboxOpacity()));
		graphics.fillRoundRect(0, 0, width - 1, height - 1, 8, 8);
	}

	private void drawExpandedShellBorder(Graphics2D graphics, int width, int height)
	{
		graphics.setColor(PANEL_BORDER);
		graphics.drawRoundRect(0, 0, width - 1, height - 1, 8, 8);
	}

	private void drawCollapsedShell(Graphics2D graphics, int width, int absX, int absY, int unreadCount, HitboxState hitboxes)
	{
		final int fontSize = plugin.getConfig().fontSize();
		final Rectangle barRect = new Rectangle(PANEL_PAD, PANEL_PAD, width - (PANEL_PAD * 2), ACTION_BAR_HEIGHT);
		final Rectangle toggleRect = positionMinimizeButton(barRect);
		hitboxes.minimizeButtonBounds = new Rectangle(absX + toggleRect.x, absY + toggleRect.y, toggleRect.width, toggleRect.height);

		graphics.setColor(shade(applyAlpha(plugin.getConfig().chatboxColor(), plugin.getConfig().chatboxOpacity()), 0.95f, plugin.getConfig().chatboxOpacity()));
		graphics.fillRoundRect(barRect.x, barRect.y, barRect.width, barRect.height, 8, 8);
		graphics.setColor(PANEL_BORDER);
		graphics.drawRoundRect(barRect.x, barRect.y, barRect.width, barRect.height, 8, 8);
		drawIconButton(graphics, toggleRect, false, hoveredMinimizeButton);

		graphics.setFont(overlayFont(Font.BOLD, Math.max(10, fontSize)));
		final FontMetrics titleFm = graphics.getFontMetrics();
		int textX = barRect.x + 8;
		if (intersectsVertically(toggleRect, barRect) && toggleRect.x <= barRect.x + (barRect.width / 2))
		{
			textX = toggleRect.x + toggleRect.width + 8;
		}

		final boolean showCollapsedBadge = plugin.getConfig().showUnreadBadge() && unreadCount > 0;
		final int badgeReserve = showCollapsedBadge ? 40 : 0;
		final int maxTitleWidth = Math.max(40, barRect.x + barRect.width - textX - 8 - badgeReserve);
		final String title = "Modern MMO PM";
		final String trimmedTitle = trimToWidth(titleFm, title, maxTitleWidth);
		final int titleBaselineY = barRect.y + ((barRect.height - titleFm.getHeight()) / 2) + titleFm.getAscent();
		drawText(graphics, trimmedTitle, textX, titleBaselineY, HEADER_TEXT);

		if (showCollapsedBadge)
		{
			final int badgeLeft = textX + titleFm.stringWidth(trimmedTitle) + 6;
			final int badgeTop = barRect.y + Math.max(2, (barRect.height - 14) / 2);
			drawUnreadBadgeAt(graphics, badgeLeft, badgeTop, unreadCount);
		}
	}

	private void drawTabs(Graphics2D graphics, List<Conversation> conversations, Rectangle tabsRect,
		ModernMmoPmConfig.TabLocation tabLocation, int absX, int absY, Color base, HitboxState hitboxes)
	{
		graphics.setColor(shade(base, 0.86f, plugin.getConfig().chatboxOpacity()));
		graphics.fillRoundRect(tabsRect.x, tabsRect.y, tabsRect.width, tabsRect.height, 8, 8);
		graphics.setColor(PANEL_BORDER);
		graphics.drawRoundRect(tabsRect.x, tabsRect.y, tabsRect.width, tabsRect.height, 8, 8);

		final int fontSize = plugin.getConfig().fontSize();
		graphics.setFont(overlayFont(Font.BOLD, fontSize));
		final FontMetrics fm = graphics.getFontMetrics();
		final boolean horizontal = tabLocation == ModernMmoPmConfig.TabLocation.TOP
			|| tabLocation == ModernMmoPmConfig.TabLocation.BOTTOM;
		final Rectangle viewportRect = new Rectangle(tabsRect.x + 4, tabsRect.y + 4,
			Math.max(0, tabsRect.width - 8), Math.max(0, tabsRect.height - 8));
		hitboxes.tabViewportHorizontal = horizontal;
		if (viewportRect.width <= 0 || viewportRect.height <= 0)
		{
			setTabScrollOffset(horizontal, 0);
			return;
		}

		final int itemSpan = horizontal ? TAB_SIZE + TAB_GAP : TAB_HEIGHT + TAB_GAP;
		final int itemSize = horizontal ? TAB_SIZE : TAB_HEIGHT;
		final int tabCount = conversations.size();
		final int totalSpan = tabCount == 0 ? 0 : itemSize + ((tabCount - 1) * itemSpan);
		final int viewportSpan = horizontal ? viewportRect.width : viewportRect.height;
		final int maxScroll = Math.max(0, totalSpan - viewportSpan);
		final Map<String, FriendListEntry> friendsByKey = new HashMap<>();
		for (FriendListEntry entry : plugin.getFriendsSnapshot())
		{
			friendsByKey.put(NameSanitizer.cleanedKey(entry.getDisplayName()), entry);
		}
		hitboxes.tabScrollMax = maxScroll;
		int tabScrollOffset = clampTabScroll(getTabScrollOffset(horizontal), maxScroll);
		final String revealKey = resolveTabRevealTarget(conversations);
		if (!tabDragArmed && !tabDragging)
		{
			tabScrollOffset = ensureTabVisible(conversations, revealKey, horizontal, tabScrollOffset, viewportSpan, maxScroll);
		}
		setTabScrollOffset(horizontal, tabScrollOffset);

		final Shape oldClip = graphics.getClip();
		graphics.setClip(viewportRect);
		int cursorX = viewportRect.x - (horizontal ? tabScrollOffset : 0);
		int cursorY = viewportRect.y - (horizontal ? 0 : tabScrollOffset);
		for (Conversation conversation : conversations)
		{
			final String key = conversation.getCleanedName();

			final Rectangle tabRect = horizontal
				? new Rectangle(cursorX, viewportRect.y + TAB_CROSS_AXIS_INSET, TAB_SIZE, Math.max(1, TAB_HEIGHT - (TAB_CROSS_AXIS_INSET * 2)))
				: new Rectangle(viewportRect.x + TAB_CROSS_AXIS_INSET, cursorY, Math.max(1, viewportRect.width - (TAB_CROSS_AXIS_INSET * 2)), TAB_HEIGHT);

			if (horizontal && tabRect.x >= viewportRect.x + viewportRect.width)
			{
				break;
			}
			if (!horizontal && tabRect.y >= viewportRect.y + viewportRect.height)
			{
				break;
			}
			if (horizontal && tabRect.x + tabRect.width <= viewportRect.x)
			{
				cursorX += TAB_SIZE + TAB_GAP;
				continue;
			}
			if (!horizontal && tabRect.y + tabRect.height <= viewportRect.y)
			{
				cursorY += TAB_HEIGHT + TAB_GAP;
				continue;
			}

			final Rectangle visibleTabRect = tabRect.intersection(viewportRect);
			hitboxes.tabBounds.put(key, new Rectangle(absX + visibleTabRect.x, absY + visibleTabRect.y, visibleTabRect.width, visibleTabRect.height));
			final Rectangle closeRect = new Rectangle(tabRect.x + tabRect.width - 15, tabRect.y + 2, 12, 12);
			final Rectangle visibleCloseRect = closeRect.intersection(viewportRect);
			if (!visibleCloseRect.isEmpty())
			{
				hitboxes.tabCloseBounds.put(key, new Rectangle(absX + visibleCloseRect.x, absY + visibleCloseRect.y,
					visibleCloseRect.width, visibleCloseRect.height));
			}

			final boolean active = !plugin.showFriendsRoster() && key.equals(plugin.getActiveConversationKey());
			final boolean hovered = key.equals(plugin.getHoveredConversationKey());

			Color tabColor = shade(base, 1.04f, plugin.getConfig().chatboxOpacity());
			Color borderColor = PANEL_BORDER;
			if (active)
			{
				tabColor = new Color(78, 92, 132, Math.max(150, Math.min(255, plugin.getConfig().chatboxOpacity() + 18)));
				borderColor = new Color(186, 200, 248, Math.max(170, plugin.getConfig().chatboxOpacity()));
			}
			else if (conversation.getFlashUntilMillis() > System.currentTimeMillis())
			{
				tabColor = new Color(125, 84, 44, Math.min(255, plugin.getConfig().chatboxOpacity() + 20));
			}
			if (hovered)
			{
				tabColor = active
					? new Color(102, 118, 166, Math.max(170, Math.min(255, plugin.getConfig().chatboxOpacity() + 26)))
					: new Color(92, 108, 148, Math.max(120, Math.min(255, plugin.getConfig().chatboxOpacity() + 20)));
				borderColor = new Color(210, 220, 255, Math.max(180, plugin.getConfig().chatboxOpacity()));
			}

			graphics.setColor(tabColor);
			graphics.fillRoundRect(tabRect.x, tabRect.y, tabRect.width, tabRect.height, 7, 7);
			graphics.setColor(borderColor);
			graphics.drawRoundRect(tabRect.x, tabRect.y, tabRect.width, tabRect.height, 7, 7);

			final String tabLabel = trimToWidth(fm, conversation.getDisplayName(), tabRect.width - 26);
			final FriendListEntry friendEntry = friendsByKey.get(conversation.getCleanedName());
			final boolean streamerMode = plugin.getConfig().streamerMode();
			final Color tabLabelColor = friendEntry == null
				? HEADER_TEXT
				: friendEntry.isOffline()
					? TIMESTAMP_TEXT
					: !streamerMode && friendEntry.isSameWorldAsLocal()
						? SAME_WORLD_FRIEND_NAME
						: plugin.getConfig().messageTextColor();
			drawText(graphics, tabLabel, tabRect.x + 5, tabRect.y + tabRect.height - 5, tabLabelColor);
			drawCloseGlyph(graphics, closeRect, key.equals(hoveredCloseConversationKey));

			if (plugin.getConfig().showUnreadBadge()
				&& conversation.getUnreadCount() > 0
				&& (plugin.showFriendsRoster() || !key.equals(plugin.getActiveConversationKey())))
			{
				drawUnreadBadge(graphics, tabRect, conversation.getUnreadCount());
			}

			if (horizontal)
			{
				cursorX += TAB_SIZE + TAB_GAP;
			}
			else
			{
				cursorY += TAB_HEIGHT + TAB_GAP;
			}
		}
		graphics.setClip(oldClip);
	}

	private void drawMainPanel(Graphics2D graphics, Conversation conversation, Rectangle mainRect, int absX, int absY, Color base,
		HitboxState hitboxes)
	{
		final boolean showFriendsRoster = plugin.showFriendsRoster();
		if (!showFriendsRoster && conversation == null)
		{
			return;
		}
		final Conversation activeConversation = conversation;

		final int opacity = plugin.getConfig().chatboxOpacity();
		final int fontSize = plugin.getConfig().fontSize();
		final Font headerFont = overlayFont(Font.BOLD, Math.max(10, fontSize));
		final Font messageFont = overlayFont(Font.PLAIN, fontSize);
		final Font timestampFont = overlayFont(Font.PLAIN, Math.max(9, fontSize - 2));
		final boolean minimizeOnBottom = plugin.getConfig().minimizeButtonLocation() == ModernMmoPmConfig.MinimizeButtonLocation.BOTTOM_LEFT
			|| plugin.getConfig().minimizeButtonLocation() == ModernMmoPmConfig.MinimizeButtonLocation.BOTTOM_RIGHT;
		final boolean showBestFriendButton = !showFriendsRoster && conversation != null;
		final int footerHeight = ACTION_BAR_HEIGHT;

		final Rectangle headerRect = new Rectangle(mainRect.x + 3, mainRect.y + 3, mainRect.width - 6, HEADER_HEIGHT);
		final Rectangle bodyRect = new Rectangle(mainRect.x + 3, headerRect.y + HEADER_HEIGHT + 3,
			mainRect.width - 6, mainRect.height - HEADER_HEIGHT - 8 - footerHeight);
		final Rectangle footerRect = new Rectangle(mainRect.x, bodyRect.y + bodyRect.height + 2,
			mainRect.width, footerHeight);
		final Rectangle toggleRect = minimizeOnBottom
			? positionFooterMinimizeButton(footerRect)
			: positionMinimizeButton(mainRect);
		final Rectangle scrollTrackRect = new Rectangle(bodyRect.x + 3, bodyRect.y + 4, SCROLLBAR_WIDTH, bodyRect.height - 8);
		final Rectangle messageRect = new Rectangle(scrollTrackRect.x + SCROLLBAR_WIDTH + 4, bodyRect.y + 2,
			bodyRect.width - SCROLLBAR_WIDTH - 9, bodyRect.height - 4);
		hitboxes.activeScrollViewportBounds = new Rectangle(absX + messageRect.x, absY + messageRect.y, messageRect.width, messageRect.height);

		graphics.setColor(shade(base, 1.05f, opacity));
		graphics.fillRoundRect(headerRect.x, headerRect.y, headerRect.width, headerRect.height, 7, 7);
		graphics.setColor(PANEL_BORDER);
		graphics.drawRoundRect(headerRect.x, headerRect.y, headerRect.width, headerRect.height, 7, 7);
		graphics.setFont(headerFont);
		hitboxes.minimizeButtonBounds = new Rectangle(absX + toggleRect.x, absY + toggleRect.y, toggleRect.width, toggleRect.height);
		if (!minimizeOnBottom)
		{
			drawIconButton(graphics, toggleRect, true, hoveredMinimizeButton);
		}
		int headerTextX = headerRect.x + 6;
		if (intersectsVertically(toggleRect, headerRect) && toggleRect.x <= headerRect.x + (headerRect.width / 2))
		{
			headerTextX = toggleRect.x + toggleRect.width + 7;
		}
		int headerTextWidth = headerRect.width - 12;
		if (intersectsVertically(toggleRect, headerRect))
		{
			if (toggleRect.x > headerRect.x + (headerRect.width / 2))
			{
				headerTextWidth = Math.max(40, toggleRect.x - headerTextX - 6);
			}
			else
			{
				headerTextWidth = Math.max(40, headerRect.x + headerRect.width - headerTextX - 6);
			}
		}
		if (showBestFriendButton)
		{
			headerTextWidth = Math.max(32, headerTextWidth - (BEST_FRIEND_HEADER_BUTTON_SIZE + 6));
		}
		final BufferedImage accountBadgeImage = showFriendsRoster ? null : accountBadgeImage(activeConversation.getAccountBadge());
		final int accountBadgeHeight = accountBadgeImage == null ? 0 : Math.min(ACCOUNT_BADGE_HEADER_SIZE, Math.max(1, headerRect.height - 4));
		final int accountBadgeWidth = accountBadgeImage == null
			? 0
			: Math.max(1, Math.round(accountBadgeImage.getWidth() * (accountBadgeHeight / (float) Math.max(1, accountBadgeImage.getHeight()))));
		final boolean showAccountBadge = accountBadgeImage != null && headerTextWidth > accountBadgeWidth + ACCOUNT_BADGE_HEADER_GAP + 24;
		if (showAccountBadge)
		{
			final int badgeY = headerRect.y + Math.max(1, (headerRect.height - accountBadgeHeight) / 2);
			graphics.drawImage(accountBadgeImage, headerTextX, badgeY, accountBadgeWidth, accountBadgeHeight, null);
			headerTextX += accountBadgeWidth + ACCOUNT_BADGE_HEADER_GAP;
			headerTextWidth = Math.max(24, headerTextWidth - accountBadgeWidth - ACCOUNT_BADGE_HEADER_GAP);
		}
		final String headerText = showFriendsRoster
			? "Friends"
			: trimToWidth(graphics.getFontMetrics(), activeConversation.getDisplayName(), headerTextWidth);
		drawText(graphics, headerText, headerTextX, headerRect.y + headerRect.height - 5, HEADER_TEXT);
		if (showBestFriendButton)
		{
			final int headerTextRight = headerTextX + graphics.getFontMetrics().stringWidth(headerText);
			int starMaxX = headerRect.x + headerRect.width - BEST_FRIEND_HEADER_BUTTON_SIZE - 4;
			if (intersectsVertically(toggleRect, headerRect) && toggleRect.x > headerRect.x + (headerRect.width / 2))
			{
				starMaxX = Math.min(starMaxX, toggleRect.x - BEST_FRIEND_HEADER_BUTTON_SIZE - 4);
			}
			final int starX = Math.min(headerTextRight + 5, starMaxX);
			final int starY = headerRect.y + Math.max(1, (headerRect.height - BEST_FRIEND_HEADER_BUTTON_SIZE) / 2);
			final Rectangle bestFriendRect = new Rectangle(starX, starY, BEST_FRIEND_HEADER_BUTTON_SIZE, BEST_FRIEND_HEADER_BUTTON_SIZE);
			hitboxes.bestFriendButtonBounds = new Rectangle(absX + bestFriendRect.x, absY + bestFriendRect.y, bestFriendRect.width, bestFriendRect.height);
			drawBestFriendButton(graphics, bestFriendRect, plugin.isBestFriendKey(activeConversation.getCleanedName()), hoveredBestFriendButton);
		}

		graphics.setColor(shade(base, 0.82f, opacity));
		graphics.fillRoundRect(bodyRect.x, bodyRect.y, bodyRect.width, bodyRect.height, 8, 8);
		graphics.setColor(PANEL_BORDER);
		graphics.drawRoundRect(bodyRect.x, bodyRect.y, bodyRect.width, bodyRect.height, 8, 8);

		graphics.setColor(shade(base, 0.94f, opacity));
		graphics.fillRoundRect(footerRect.x, footerRect.y, footerRect.width, footerRect.height, 7, 7);
		graphics.setColor(PANEL_BORDER);
		graphics.drawRoundRect(footerRect.x, footerRect.y, footerRect.width, footerRect.height, 7, 7);

		if (minimizeOnBottom)
		{
			drawIconButton(graphics, toggleRect, true, hoveredMinimizeButton);
		}

		final Rectangle pmRect = new Rectangle();
		final Rectangle friendsRect = new Rectangle();
		layoutFooterActionButtons(footerRect, toggleRect, minimizeOnBottom, pmRect, friendsRect);
		hitboxes.pmActionButtonBounds = new Rectangle(absX + pmRect.x, absY + pmRect.y, pmRect.width, pmRect.height);
		hitboxes.friendsActionButtonBounds = new Rectangle(absX + friendsRect.x, absY + friendsRect.y, friendsRect.width, friendsRect.height);
		drawMailButton(graphics, pmRect, hoveredPmActionButton);
		drawFriendsActionButton(graphics, friendsRect, "Friends", hoveredFriendsActionButton, showFriendsRoster);

		final FontMetrics messageFm = graphics.getFontMetrics(messageFont);
		if (showFriendsRoster)
		{
			drawFriendsRoster(graphics, messageRect, scrollTrackRect, absX, absY, messageFont, fontSize, hitboxes);
			return;
		}

		final List<ConversationMessage> messages = activeConversation.getMessagesView();
		final Color incomingBubbleColor = applyAlpha(plugin.getConfig().receiverBubbleColor(), plugin.getConfig().receiverBubbleOpacity());
		final Color outgoingBubbleColor = applyAlpha(plugin.getConfig().senderBubbleColor(), plugin.getConfig().senderBubbleOpacity());
		final int maxBubbleWidth = (int) (messageRect.width * 0.72f);
		final Font emojiFont = scaledEmojiFontFor(messageFont);
		final FontMetrics emojiFm = emojiFont != null ? graphics.getFontMetrics(emojiFont) : messageFm;
		final List<MessageLayout> layouts = new ArrayList<>(messages.size());
		int totalHeight = 0;
		for (ConversationMessage message : messages)
		{
			final MessageLayout layout = layoutMessage(messageFm, emojiFm, message, maxBubbleWidth);
			layouts.add(layout);
			totalHeight += layout.bubbleHeight + 4;
		}
		if (totalHeight > 0)
		{
			totalHeight -= 4;
		}

		final int maxScroll = Math.max(0, totalHeight - Math.max(0, messageRect.height - 4));
		final int clampedScroll = Math.max(0, Math.min(activeConversation.getScrollOffset(), maxScroll));
		if (clampedScroll != activeConversation.getScrollOffset())
		{
			activeConversation.setScrollOffset(clampedScroll);
		}
		hitboxes.scrollMaxByConversation.put(activeConversation.getCleanedName(), maxScroll);

		final Shape oldClip = graphics.getClip();
		graphics.setClip(messageRect);
		int yCursor = messageRect.y + messageRect.height - 4 + clampedScroll;
		for (int i = messages.size() - 1; i >= 0; i--)
		{
			final ConversationMessage message = messages.get(i);
			final MessageLayout layout = layouts.get(i);
			final int bubbleHeight = layout.bubbleHeight;
			final int bubbleWidth = layout.bubbleWidth;
			final int bubbleX = message.isIncoming()
				? messageRect.x + 2
				: messageRect.x + messageRect.width - bubbleWidth - 2;
			final int bubbleY = yCursor - bubbleHeight;

			if (bubbleY > messageRect.y + messageRect.height)
			{
				yCursor = bubbleY - 4;
				continue;
			}
			if (bubbleY + bubbleHeight < messageRect.y)
			{
				break;
			}

			final Color bubbleColor = message.isIncoming() ? incomingBubbleColor : outgoingBubbleColor;
			graphics.setColor(bubbleColor);
			graphics.fillRoundRect(bubbleX, bubbleY, bubbleWidth, bubbleHeight, 11, 11);

			final Shape preBubbleClip = graphics.getClip();
			graphics.clipRect(bubbleX + 1, bubbleY + 1, Math.max(0, bubbleWidth - 2), Math.max(0, bubbleHeight - 2));
			graphics.setColor(plugin.getConfig().messageTextColor());
			graphics.setFont(messageFont);
			int textY = bubbleY + fontSize + 1;
			for (PmMessageFormatter.StyledLine line : layout.lines)
			{
				int textX = bubbleX + BUBBLE_PAD;
				for (PmMessageFormatter.StyledRun run : line.getRuns())
				{
					if (run.getText().isEmpty())
					{
						continue;
					}
					if (run.isChatIcon())
					{
						final BufferedImage chatIconImage = chatIconImage(run.getChatIconId());
						if (chatIconImage != null)
						{
							final int iconSize = chatIconSize(messageFm);
							final int iconY = textY - messageFm.getAscent() + Math.max(0, (messageFm.getHeight() - iconSize) / 2);
							graphics.drawImage(chatIconImage, textX, iconY, iconSize, iconSize, null);
							textX += iconSize;
						}
						else
						{
							graphics.setFont(messageFont);
							drawText(graphics, run.getText(), textX, textY, run.getColor());
							textX += messageFm.stringWidth(run.getText());
						}
						continue;
					}
					final Font runFont = run.isEmoji() && emojiFont != null ? emojiFont : messageFont;
					final FontMetrics runFm = run.isEmoji() ? emojiFm : messageFm;
					graphics.setFont(runFont);
					drawText(graphics, run.getText(), textX, textY, run.getColor());
					textX += runFm.stringWidth(run.getText());
				}
				graphics.setFont(messageFont);
				textY += fontSize + 2;
			}
			graphics.setClip(preBubbleClip);

			if (plugin.getConfig().showTimestamps())
			{
				graphics.setFont(timestampFont);
				final String ts = TIME_FMT.format(message.getTimestamp());
				final FontMetrics tsFm = graphics.getFontMetrics();
				drawText(graphics, ts, bubbleX + bubbleWidth - tsFm.stringWidth(ts) - 5, bubbleY + bubbleHeight - 4, TIMESTAMP_TEXT);
			}
			yCursor = bubbleY - 4;
		}
		graphics.setClip(oldClip);

		graphics.setColor(hoveredScrollbar ? new Color(32, 38, 48, 150) : SCROLLBAR_TRACK);
		graphics.fillRoundRect(scrollTrackRect.x, scrollTrackRect.y, scrollTrackRect.width, scrollTrackRect.height, 6, 6);

		final int thumbHeight = maxScroll == 0
			? scrollTrackRect.height
			: Math.max(SCROLLBAR_MIN_THUMB, (int) ((messageRect.height / (float) Math.max(messageRect.height + maxScroll, 1)) * scrollTrackRect.height));
		final int thumbTravel = Math.max(0, scrollTrackRect.height - thumbHeight);
		final int thumbY = maxScroll == 0
			? scrollTrackRect.y
			: scrollTrackRect.y + Math.round(((maxScroll - clampedScroll) / (float) maxScroll) * thumbTravel);
		final Rectangle thumbRect = new Rectangle(scrollTrackRect.x, thumbY, scrollTrackRect.width, thumbHeight);

		graphics.setColor(hoveredScrollbar ? new Color(155, 166, 196, 235) : SCROLLBAR_THUMB);
		graphics.fillRoundRect(thumbRect.x, thumbRect.y, thumbRect.width, thumbRect.height, 6, 6);

		hitboxes.activeScrollbarTrackBounds = new Rectangle(absX + scrollTrackRect.x, absY + scrollTrackRect.y, scrollTrackRect.width, scrollTrackRect.height);
		hitboxes.activeScrollbarThumbBounds = new Rectangle(absX + thumbRect.x, absY + thumbRect.y, thumbRect.width, thumbRect.height);
	}

	private void drawUnreadBadge(Graphics2D graphics, Rectangle rect, int unreadCount)
	{
		drawUnreadBadgeAt(graphics, rect.x + 4, rect.y + 4, unreadCount);
	}

	private void drawUnreadBadgeAt(Graphics2D graphics, int badgeLeftX, int badgeTopY, int unreadCount)
	{
		final String text = unreadCount > 99 ? "99+" : Integer.toString(unreadCount);
		graphics.setFont(overlayFont(Font.BOLD, Math.max(9, plugin.getConfig().fontSize() - 1)));
		final FontMetrics badgeFm = graphics.getFontMetrics();
		final int badgeWidth = Math.max(16, badgeFm.stringWidth(text) + 8);
		graphics.setColor(BADGE_BG);
		graphics.fillRoundRect(badgeLeftX, badgeTopY, badgeWidth, 14, 14, 14);
		drawText(graphics, text, badgeLeftX + (badgeWidth - badgeFm.stringWidth(text)) / 2, badgeTopY + 11, Color.WHITE);
	}

	private void layoutFooterActionButtons(Rectangle footerRect, Rectangle minimizeRect, boolean minimizeOnBottom,
		Rectangle outPm, Rectangle outFriends)
	{
		final int y = footerButtonY(footerRect);
		int x = footerRect.x + 4;
		if (minimizeOnBottom && plugin.getConfig().minimizeButtonLocation() == ModernMmoPmConfig.MinimizeButtonLocation.BOTTOM_LEFT)
		{
			x = Math.max(x, minimizeRect.x + minimizeRect.width + FOOTER_BUTTON_GAP);
		}
		final int totalWidth = PM_BUTTON_WIDTH + FOOTER_BUTTON_GAP + FRIENDS_BUTTON_WIDTH;
		final int maxRight = footerRect.x + footerRect.width - 4;
		x = Math.min(x, Math.max(footerRect.x + 4, maxRight - totalWidth));
		outPm.setBounds(x, y, PM_BUTTON_WIDTH, ICON_BUTTON_SIZE);
		outFriends.setBounds(x + PM_BUTTON_WIDTH + FOOTER_BUTTON_GAP, y, FRIENDS_BUTTON_WIDTH, ICON_BUTTON_SIZE);
	}

	private void drawFriendsActionButton(Graphics2D graphics, Rectangle rect, String label, boolean hovered, boolean active)
	{
		final Color idleFill = new Color(14, 18, 26, 236);
		final Color activeFill = new Color(28, 90, 48, 236);
		final Color hoverFill = new Color(34, 112, 56, 242);
		final Color idleBorder = new Color(170, 184, 222, 244);
		final Color activeBorder = new Color(90, 200, 118, 232);
		final Color hoverBorder = new Color(118, 224, 142, 248);

		final Color fill;
		final Color border;
		if (hovered)
		{
			fill = hoverFill;
			border = hoverBorder;
		}
		else if (active)
		{
			fill = activeFill;
			border = activeBorder;
		}
		else
		{
			fill = idleFill;
			border = idleBorder;
		}
		graphics.setColor(fill);
		graphics.fillRoundRect(rect.x, rect.y, rect.width, rect.height, 5, 5);
		graphics.setColor(border);
		graphics.drawRoundRect(rect.x, rect.y, rect.width, rect.height, 5, 5);
		graphics.setFont(overlayFont(Font.BOLD, Math.max(9, plugin.getConfig().fontSize() - 1)));
		final FontMetrics fm = graphics.getFontMetrics();
		drawText(graphics, label,
			rect.x + Math.max(2, (rect.width - fm.stringWidth(label)) / 2),
			rect.y + ((rect.height + fm.getAscent()) / 2) - 2,
			HEADER_TEXT);
	}

	private void drawFriendsRoster(Graphics2D graphics, Rectangle messageRect, Rectangle scrollTrackRect, int absX, int absY,
		Font messageFont, int fontSize, HitboxState hitboxes)
	{
		final List<FriendListEntry> friends = plugin.getFriendsSnapshot();
		final int rowHeight = fontSize + 6;
		final int totalHeight = friends.isEmpty() ? 0 : friends.size() * rowHeight;
		final int maxScroll = Math.max(0, totalHeight - Math.max(0, messageRect.height - 4));
		final int clampedScroll = Math.max(0, Math.min(friendsListScrollOffset, maxScroll));
		if (clampedScroll != friendsListScrollOffset)
		{
			friendsListScrollOffset = clampedScroll;
		}
		hitboxes.scrollMaxByConversation.put(ModernMmoPmPlugin.FRIENDS_SCROLL_KEY, maxScroll);

		final Shape oldClip = graphics.getClip();
		graphics.setClip(messageRect);
		graphics.setFont(messageFont);
		final FontMetrics rowFm = graphics.getFontMetrics();
		final int rowPadH = 4;
		final int starBaseX = messageRect.x + 6;
		final int nameBaseX = starBaseX + BEST_FRIEND_ROSTER_STAR_SLOT;
		final int worldGap = 14;
		final int regionGap = 6;
		final int regionTextGap = 4;
		if (friends.isEmpty())
		{
			drawText(graphics, "No friends on list (log in to load)", messageRect.x + 6, messageRect.y + fontSize + 2, TIMESTAMP_TEXT);
		}
		else
		{
			final boolean streamerMode = plugin.getConfig().streamerMode();
			int maxNameWidth = 0;
			int maxWorldWidth = 0;
			for (FriendListEntry entry : friends)
			{
				maxNameWidth = Math.max(maxNameWidth, rowFm.stringWidth(entry.getDisplayName()));
				if (!entry.isOffline())
				{
					final String label = streamerMode ? "???" : String.valueOf(entry.getWorld());
					maxWorldWidth = Math.max(maxWorldWidth, rowFm.stringWidth(label));
				}
			}
			final int worldColX = nameBaseX + maxNameWidth + worldGap;
			final int flagColX = worldColX + maxWorldWidth + regionGap;
			final int regionColX = flagColX + FRIEND_REGION_FLAG_WIDTH + regionTextGap;

			int y = messageRect.y + 4 - clampedScroll;
			for (FriendListEntry entry : friends)
			{
				final String rowKey = Integer.toString(entry.getRowIndex());
				final String name = entry.getDisplayName();
				final int nameWidth = rowFm.stringWidth(name);
				final String worldLabel = entry.isOffline()
					? ""
					: streamerMode ? "???" : String.valueOf(entry.getWorld());
				final int worldWidth = entry.isOffline() ? 0 : rowFm.stringWidth(worldLabel);
				final WorldRegion worldRegion = streamerMode ? null : entry.getWorldRegion();
				final int regionWidth = worldRegion == null ? 0 : rowFm.stringWidth(worldRegion.getCode());
				final int baselineY = y + fontSize;
				if (y + rowHeight >= messageRect.y && y <= messageRect.y + messageRect.height)
				{
					final int rowTop = Math.max(y, messageRect.y);
					final int rowBottom = Math.min(y + rowHeight, messageRect.y + messageRect.height);
					final int rowTopAbs = absY + rowTop;
					final int rowBottomAbs = absY + rowBottom;
					final int hitX = starBaseX - rowPadH;
					final int rowContentRight = entry.isOffline()
						? nameBaseX + nameWidth
						: worldRegion == null
							? worldColX + worldWidth
							: regionColX + regionWidth;
					final int hitW = Math.max(0, (rowContentRight + rowPadH) - hitX);
					final int hitH = rowBottomAbs - rowTopAbs;
					if (hitH > 0 && hitW > 0)
					{
						final Rectangle nameHitAbs = new Rectangle(absX + hitX, rowTopAbs, hitW, hitH);
						hitboxes.friendRowHitBounds.put(rowKey, nameHitAbs);
					}
					if (rowKey.equals(hoveredFriendRowKey))
					{
						graphics.setColor(new Color(60, 70, 95, 180));
						graphics.fillRoundRect(hitX, rowTop, hitW, hitH, 6, 6);
					}
					final Color nameColor;
					final Color worldColor;
					if (entry.isOffline())
					{
						nameColor = TIMESTAMP_TEXT;
						worldColor = TIMESTAMP_TEXT;
					}
					else if (!streamerMode && entry.isSameWorldAsLocal())
					{
						nameColor = SAME_WORLD_FRIEND_NAME;
						worldColor = SAME_WORLD_FRIEND_NAME;
					}
					else
					{
						nameColor = plugin.getConfig().messageTextColor();
						worldColor = plugin.getConfig().messageTextColor();
					}
					if (entry.isBestFriend())
					{
						drawStar(graphics, starBaseX + 4, rowTop + Math.max(6, hitH / 2), 4, 2, new Color(255, 203, 79), new Color(104, 74, 20));
					}
					drawText(graphics, name, nameBaseX, baselineY, nameColor);
					if (!entry.isOffline())
					{
						drawText(graphics, worldLabel, worldColX, baselineY, worldColor);
						if (worldRegion != null)
						{
							drawWorldRegionFlag(graphics, worldRegion, flagColX, baselineY);
							drawText(graphics, worldRegion.getCode(), regionColX, baselineY, worldColor);
						}
					}
				}
				y += rowHeight;
			}
		}
		graphics.setClip(oldClip);

		graphics.setColor(hoveredScrollbar ? new Color(32, 38, 48, 150) : SCROLLBAR_TRACK);
		graphics.fillRoundRect(scrollTrackRect.x, scrollTrackRect.y, scrollTrackRect.width, scrollTrackRect.height, 6, 6);

		final int thumbHeight = maxScroll == 0
			? scrollTrackRect.height
			: Math.max(SCROLLBAR_MIN_THUMB, (int) ((messageRect.height / (float) Math.max(messageRect.height + maxScroll, 1)) * scrollTrackRect.height));
		final int thumbTravel = Math.max(0, scrollTrackRect.height - thumbHeight);
		final int thumbY = maxScroll == 0
			? scrollTrackRect.y
			: scrollTrackRect.y + Math.round((clampedScroll / (float) maxScroll) * thumbTravel);
		final Rectangle thumbRect = new Rectangle(scrollTrackRect.x, thumbY, scrollTrackRect.width, thumbHeight);

		graphics.setColor(hoveredScrollbar ? new Color(155, 166, 196, 235) : SCROLLBAR_THUMB);
		graphics.fillRoundRect(thumbRect.x, thumbRect.y, thumbRect.width, thumbRect.height, 6, 6);

		hitboxes.activeScrollbarTrackBounds = new Rectangle(absX + scrollTrackRect.x, absY + scrollTrackRect.y, scrollTrackRect.width, scrollTrackRect.height);
		hitboxes.activeScrollbarThumbBounds = new Rectangle(absX + thumbRect.x, absY + thumbRect.y, thumbRect.width, thumbRect.height);
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent mouseEvent)
	{
		return mouseEvent;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent mouseEvent)
	{
		if (isAltDrag(mouseEvent))
		{
			return mouseEvent;
		}

		final Point point = mouseEvent.getPoint();
		if (minimizeButtonBounds != null && minimizeButtonBounds.contains(point) && mouseEvent.getButton() == MouseEvent.BUTTON1)
		{
			plugin.toggleMinimized();
			revalidate();
			mouseEvent.consume();
			return mouseEvent;
		}

		if (bestFriendButtonBounds != null && bestFriendButtonBounds.contains(point) && mouseEvent.getButton() == MouseEvent.BUTTON1)
		{
			plugin.toggleBestFriend(plugin.getActiveConversationKey());
			revalidate();
			mouseEvent.consume();
			return mouseEvent;
		}

		if (pmActionButtonBounds != null && pmActionButtonBounds.contains(point) && mouseEvent.getButton() == MouseEvent.BUTTON1)
		{
			plugin.openPmInputForActiveConversation();
			revalidate();
			mouseEvent.consume();
			return mouseEvent;
		}

		if (friendsActionButtonBounds != null && friendsActionButtonBounds.contains(point) && mouseEvent.getButton() == MouseEvent.BUTTON1)
		{
			plugin.setFriendsViewActive(true);
			plugin.setMinimized(false);
			revalidate();
			mouseEvent.consume();
			return mouseEvent;
		}

		if (plugin.showFriendsRoster() && mouseEvent.getButton() == MouseEvent.BUTTON1)
		{
			for (Map.Entry<String, Rectangle> entry : friendRowHitBounds.entrySet())
			{
				if (entry.getValue().contains(point))
				{
					final List<FriendListEntry> roster = plugin.getFriendsSnapshot();
					try
					{
						final int idx = Integer.parseInt(entry.getKey());
						if (idx >= 0 && idx < roster.size())
						{
							plugin.openPrivateMessageToFriend(roster.get(idx).getDisplayName());
						}
					}
					catch (NumberFormatException ignored)
					{
					}
					revalidate();
					mouseEvent.consume();
					return mouseEvent;
				}
			}
		}

		for (Map.Entry<String, Rectangle> entry : tabCloseBounds.entrySet())
		{
			if (!entry.getValue().contains(point) || mouseEvent.getButton() != MouseEvent.BUTTON1)
			{
				continue;
			}

			plugin.closeConversation(entry.getKey());
			revalidate();
			mouseEvent.consume();
			return mouseEvent;
		}

		for (Map.Entry<String, Rectangle> entry : tabBounds.entrySet())
		{
			if (!entry.getValue().contains(point))
			{
				continue;
			}

			plugin.setHoveredConversationKey(entry.getKey());
			if (mouseEvent.getButton() == MouseEvent.BUTTON1)
			{
				if (tabScrollMax > 0)
				{
					armTabDrag(entry.getKey(), point);
				}
				else
				{
					plugin.setActiveConversation(entry.getKey());
					revalidate();
				}
				mouseEvent.consume();
			}
			return mouseEvent;
		}

		final String scrollTargetKey = plugin.showFriendsRoster()
			? ModernMmoPmPlugin.FRIENDS_SCROLL_KEY
			: plugin.getActiveConversationKey();
		if (scrollTargetKey != null && activeScrollbarThumbBounds != null && activeScrollbarThumbBounds.contains(point) && mouseEvent.getButton() == MouseEvent.BUTTON1)
		{
			draggingConversationKey = scrollTargetKey;
			scrollbarDragOffsetY = point.y - activeScrollbarThumbBounds.y;
			mouseEvent.consume();
			return mouseEvent;
		}

		if (scrollTargetKey != null && activeScrollbarTrackBounds != null && activeScrollbarTrackBounds.contains(point) && mouseEvent.getButton() == MouseEvent.BUTTON1)
		{
			final int thumbCenter = activeScrollbarThumbBounds == null ? 0 : activeScrollbarThumbBounds.height / 2;
			updateScrollFromPointer(scrollTargetKey, point.y - thumbCenter);
			draggingConversationKey = scrollTargetKey;
			scrollbarDragOffsetY = thumbCenter;
			revalidate();
			mouseEvent.consume();
		}

		return mouseEvent;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent mouseEvent)
	{
		if (tabDragArmed || tabDragging)
		{
			final String pressedKey = pressedTabConversationKey;
			final boolean wasDragging = tabDragging;
			clearTabDragState();
			if (!wasDragging && pressedKey != null)
			{
				final Rectangle tabRect = tabBounds.get(pressedKey);
				if (tabRect != null && tabRect.contains(mouseEvent.getPoint()))
				{
					plugin.setHoveredConversationKey(pressedKey);
					plugin.setActiveConversation(pressedKey);
					revalidate();
				}
			}
			mouseEvent.consume();
		}

		draggingConversationKey = null;
		scrollbarDragOffsetY = 0;
		return mouseEvent;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent mouseEvent)
	{
		return mouseEvent;
	}

	@Override
	public MouseEvent mouseExited(MouseEvent mouseEvent)
	{
		final boolean hadHoverState = plugin.getHoveredConversationKey() != null
			|| hoveredCloseConversationKey != null
			|| hoveredMinimizeButton
			|| hoveredBestFriendButton
			|| hoveredPmActionButton
			|| hoveredFriendsActionButton
			|| hoveredFriendRowKey != null
			|| hoveredScrollbar;
		plugin.setHoveredConversationKey(null);
		hoveredCloseConversationKey = null;
		hoveredMinimizeButton = false;
		hoveredBestFriendButton = false;
		hoveredPmActionButton = false;
		hoveredFriendsActionButton = false;
		hoveredFriendRowKey = null;
		hoveredScrollbar = false;
		draggingConversationKey = null;
		scrollbarDragOffsetY = 0;
		lastPointerPosition = null;
		clearTabDragState();
		if (hadHoverState)
		{
			revalidate();
		}
		return mouseEvent;
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent mouseWheelEvent)
	{
		if (!plugin.getConfig().mouseWheelChatScroll()
			|| plugin.isMinimized()
			|| activeScrollViewportBounds == null
			|| !activeScrollViewportBounds.contains(mouseWheelEvent.getPoint()))
		{
			return mouseWheelEvent;
		}

		final int delta = (int) Math.round(mouseWheelEvent.getPreciseWheelRotation() * CHAT_WHEEL_SCROLL_PIXELS);
		if (plugin.showFriendsRoster())
		{
			final int maxScroll = scrollMaxByConversation.getOrDefault(ModernMmoPmPlugin.FRIENDS_SCROLL_KEY, 0);
			if (maxScroll <= 0)
			{
				friendsListScrollOffset = 0;
				return mouseWheelEvent;
			}

			final int nextScroll = Math.max(0, Math.min(maxScroll, friendsListScrollOffset + delta));
			if (nextScroll != friendsListScrollOffset)
			{
				friendsListScrollOffset = nextScroll;
				revalidate();
			}
			mouseWheelEvent.consume();
			return mouseWheelEvent;
		}

		final Conversation conversation = plugin.getActiveConversation();
		if (conversation == null)
		{
			return mouseWheelEvent;
		}

		final int maxScroll = scrollMaxByConversation.getOrDefault(conversation.getCleanedName(), 0);
		if (maxScroll <= 0)
		{
			conversation.setScrollOffset(0);
			return mouseWheelEvent;
		}

		final int nextScroll = Math.max(0, Math.min(maxScroll, conversation.getScrollOffset() - delta));
		if (nextScroll != conversation.getScrollOffset())
		{
			conversation.setScrollOffset(nextScroll);
			revalidate();
		}
		mouseWheelEvent.consume();
		return mouseWheelEvent;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent mouseEvent)
	{
		if (tabDragArmed || tabDragging)
		{
			final int pointer = tabDragHorizontal ? mouseEvent.getX() : mouseEvent.getY();
			final int delta = pointer - tabDragPointerStart;
			if (!tabDragging && Math.abs(delta) >= TAB_DRAG_THRESHOLD)
			{
				tabDragging = true;
			}

			if (tabDragging)
			{
				final int nextOffset = clampTabScroll(tabDragScrollStart - delta, tabScrollMax);
				if (nextOffset != getTabScrollOffset(tabDragHorizontal))
				{
					setTabScrollOffset(tabDragHorizontal, nextOffset);
					revalidate();
				}
			}
			mouseEvent.consume();
			return mouseEvent;
		}

		if (draggingConversationKey != null)
		{
			updateScrollFromPointer(draggingConversationKey, mouseEvent.getY() - scrollbarDragOffsetY);
			lastPointerPosition = mouseEvent.getPoint();
			revalidate();
			mouseEvent.consume();
		}
		return mouseEvent;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent mouseEvent)
	{
		final Point point = mouseEvent.getPoint();
		lastPointerPosition = point;
		final boolean nextHoveredMinimizeButton = minimizeButtonBounds != null && minimizeButtonBounds.contains(point);
		final boolean nextHoveredBestFriendButton = bestFriendButtonBounds != null && bestFriendButtonBounds.contains(point);
		final boolean nextHoveredPmActionButton = pmActionButtonBounds != null && pmActionButtonBounds.contains(point);
		final boolean nextHoveredFriendsActionButton = friendsActionButtonBounds != null && friendsActionButtonBounds.contains(point);
		String nextHoveredFriend = null;
		if (plugin.showFriendsRoster())
		{
			for (Map.Entry<String, Rectangle> entry : friendRowHitBounds.entrySet())
			{
				if (entry.getValue().contains(point))
				{
					nextHoveredFriend = entry.getKey();
					break;
				}
			}
		}
		String nextHoveredCloseConversationKey = null;
		for (Map.Entry<String, Rectangle> entry : tabCloseBounds.entrySet())
		{
			if (entry.getValue().contains(point))
			{
				nextHoveredCloseConversationKey = entry.getKey();
				break;
			}
		}
		final boolean nextHoveredScrollbar = (activeScrollbarThumbBounds != null && activeScrollbarThumbBounds.contains(point))
			|| (activeScrollbarTrackBounds != null && activeScrollbarTrackBounds.contains(point));

		String nextHoveredConversationKey = null;
		for (Map.Entry<String, Rectangle> entry : tabBounds.entrySet())
		{
			if (entry.getValue().contains(point))
			{
				nextHoveredConversationKey = entry.getKey();
				break;
			}
		}

		final boolean hoverChanged = hoveredMinimizeButton != nextHoveredMinimizeButton
			|| hoveredBestFriendButton != nextHoveredBestFriendButton
			|| hoveredPmActionButton != nextHoveredPmActionButton
			|| hoveredFriendsActionButton != nextHoveredFriendsActionButton
			|| hoveredScrollbar != nextHoveredScrollbar
			|| !Objects.equals(hoveredFriendRowKey, nextHoveredFriend)
			|| !Objects.equals(hoveredCloseConversationKey, nextHoveredCloseConversationKey)
			|| !Objects.equals(plugin.getHoveredConversationKey(), nextHoveredConversationKey);
		hoveredMinimizeButton = nextHoveredMinimizeButton;
		hoveredBestFriendButton = nextHoveredBestFriendButton;
		hoveredPmActionButton = nextHoveredPmActionButton;
		hoveredFriendsActionButton = nextHoveredFriendsActionButton;
		hoveredFriendRowKey = nextHoveredFriend;
		hoveredCloseConversationKey = nextHoveredCloseConversationKey;
		hoveredScrollbar = nextHoveredScrollbar;
		plugin.setHoveredConversationKey(nextHoveredConversationKey);
		if (hoverChanged)
		{
			revalidate();
		}
		return mouseEvent;
	}

	private void applyHitboxState(HitboxState hitboxes)
	{
		tabBounds = hitboxes.tabBounds;
		tabCloseBounds = hitboxes.tabCloseBounds;
		friendRowHitBounds = hitboxes.friendRowHitBounds;
		scrollMaxByConversation = hitboxes.scrollMaxByConversation;
		tabViewportHorizontal = hitboxes.tabViewportHorizontal;
		tabScrollMax = hitboxes.tabScrollMax;
		minimizeButtonBounds = hitboxes.minimizeButtonBounds;
		bestFriendButtonBounds = hitboxes.bestFriendButtonBounds;
		pmActionButtonBounds = hitboxes.pmActionButtonBounds;
		friendsActionButtonBounds = hitboxes.friendsActionButtonBounds;
		activeScrollViewportBounds = hitboxes.activeScrollViewportBounds;
		activeScrollbarTrackBounds = hitboxes.activeScrollbarTrackBounds;
		activeScrollbarThumbBounds = hitboxes.activeScrollbarThumbBounds;
		if (plugin.getHoveredConversationKey() != null && !tabBounds.containsKey(plugin.getHoveredConversationKey()))
		{
			plugin.setHoveredConversationKey(null);
		}
		if (hoveredCloseConversationKey != null && !tabCloseBounds.containsKey(hoveredCloseConversationKey))
		{
			hoveredCloseConversationKey = null;
		}
		if (lastPointerPosition != null && plugin.showFriendsRoster())
		{
			String resolvedHover = null;
			for (Map.Entry<String, Rectangle> entry : friendRowHitBounds.entrySet())
			{
				if (entry.getValue().contains(lastPointerPosition))
				{
					resolvedHover = entry.getKey();
					break;
				}
			}
			hoveredFriendRowKey = resolvedHover;
		}
		else if (hoveredFriendRowKey != null && !friendRowHitBounds.containsKey(hoveredFriendRowKey))
		{
			hoveredFriendRowKey = null;
		}
	}

	private MessageLayout layoutMessage(FontMetrics textMetrics, FontMetrics emojiMetrics, ConversationMessage message, int maxBubbleWidth)
	{
		final String displayText = plugin.getConfig().enableEmojis()
			? EmojiTextFormatter.replaceShortcodes(message.getText())
			: message.getText();
		final List<PmMessageFormatter.StyledRun> runs = PmMessageFormatter.parseRuns(displayText, plugin.getConfig().messageTextColor());
		final List<PmMessageFormatter.StyledLine> lines = PmMessageFormatter.wrapRuns(textMetrics, emojiMetrics, runs, maxBubbleWidth - (BUBBLE_PAD * 2));
		int widestLine = 28;
		for (PmMessageFormatter.StyledLine line : lines)
		{
			widestLine = Math.max(widestLine, line.getWidth());
		}

		final int bubbleWidth = Math.min(maxBubbleWidth, widestLine + (BUBBLE_PAD * 2));
		final int bubbleHeight = (lines.size() * (plugin.getConfig().fontSize() + 2)) + 14;
		return new MessageLayout(lines, bubbleWidth, bubbleHeight);
	}

	private static int chatIconSize(FontMetrics textMetrics)
	{
		return Math.max(1, textMetrics.getHeight());
