	private BufferedImage chatIconImage(int iconId)
	{
		if (iconId < 0)
		{
			return null;
		}

		final BufferedImage cached = chatIconImages.get(iconId);
		if (cached != null)
		{
			return cached;
		}

		final IndexedSprite[] modIcons = client.getModIcons();
		if (modIcons == null || iconId >= modIcons.length || modIcons[iconId] == null)
		{
			return null;
		}

		final BufferedImage image = indexedSpriteToImage(modIcons[iconId]);
		if (image != null)
		{
			chatIconImages.put(iconId, image);
		}
		return image;
	}

	private static BufferedImage indexedSpriteToImage(IndexedSprite sprite)
	{
		final int width = sprite.getWidth();
		final int height = sprite.getHeight();
		final byte[] pixels = sprite.getPixels();
		final int[] palette = sprite.getPalette();
		if (width <= 0 || height <= 0 || pixels == null || palette == null)
		{
			return null;
		}

		final BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		final int pixelCount = Math.min(width * height, pixels.length);
		for (int i = 0; i < pixelCount; i++)
		{
			final int paletteIndex = pixels[i] & 0xFF;
			if (paletteIndex <= 0 || paletteIndex >= palette.length)
			{
				continue;
			}

			int color = palette[paletteIndex];
			if ((color & 0xFF000000) == 0)
			{
				color |= 0xFF000000;
			}
			image.setRGB(i % width, i / width, color);
		}
		return image;
	}

	private BufferedImage accountBadgeImage(AccountBadge badge)
	{
		if (badge == null)
		{
			return null;
		}

		if (accountBadgeImages.containsKey(badge))
		{
			return accountBadgeImages.get(badge);
		}

		BufferedImage image = null;
		final URL resource = getClass().getResource("/ico/" + badge.getIconFileName());
		if (resource != null)
		{
			try
			{
				image = ImageIO.read(resource);
			}
			catch (IOException ignored)
			{
				// Missing or unreadable badge resources should not break overlay rendering.
			}
		}
		accountBadgeImages.put(badge, image);
		return image;
	}

	private Font overlayFont(int style, int size)
	{
		return new Font(resolveFontFamily(), style, size);
	}

	private Font scaledEmojiFontFor(Font baseFont)
	{
		final String emojiFamily = resolveEmojiFontFamily();
		if (emojiFamily == null || emojiFamily.equalsIgnoreCase(baseFont.getFamily()))
		{
			return null;
		}

		if (cachedScaledEmojiFont != null
			&& emojiFamily.equals(cachedScaledEmojiFontFamily)
			&& baseFont.getSize() == cachedScaledEmojiTextSize
			&& baseFont.getStyle() == cachedScaledEmojiTextStyle)
		{
			return cachedScaledEmojiFont;
		}

		final Graphics2D measureGraphics = scaledEmojiMeasurement.createGraphics();
		try
		{
			final FontMetrics textMetrics = measureGraphics.getFontMetrics(baseFont);
			final int textAscent = textMetrics.getAscent();
			final int textHeight = textMetrics.getHeight();
			Font candidate = null;
			for (int size = baseFont.getSize(); size >= 6; size--)
			{
				final Font next = new Font(emojiFamily, baseFont.getStyle(), size);
				final FontMetrics fm = measureGraphics.getFontMetrics(next);
				if (fm.getAscent() <= textAscent && fm.getHeight() <= textHeight)
				{
					candidate = next;
					break;
				}
			}
			if (candidate == null)
			{
				candidate = new Font(emojiFamily, baseFont.getStyle(), Math.max(6, baseFont.getSize() - 2));
			}
			cachedScaledEmojiFont = candidate;
			cachedScaledEmojiFontFamily = emojiFamily;
			cachedScaledEmojiTextSize = baseFont.getSize();
			cachedScaledEmojiTextStyle = baseFont.getStyle();
			return cachedScaledEmojiFont;
		}
		finally
		{
			measureGraphics.dispose();
		}
	}

	private String resolveFontFamily()
	{
		final String configured = plugin.getConfig().fontFamily();
		final String configKey = configured == null ? "" : configured.trim();
		if (cachedFontFamily != null && configKey.equals(cachedFontFamilyConfig))
		{
			return cachedFontFamily;
		}

		cachedFontFamilyConfig = configKey;
		if (configKey.isEmpty())
		{
			cachedFontFamily = DEFAULT_FONT_FAMILY;
			return cachedFontFamily;
		}

		for (String family : AVAILABLE_FONT_FAMILIES)
		{
			if (family.equalsIgnoreCase(configKey))
			{
				cachedFontFamily = family;
				return cachedFontFamily;
			}
		}

		cachedFontFamily = DEFAULT_FONT_FAMILY;
		return cachedFontFamily;
	}

	private String resolveEmojiFontFamily()
	{
		if (cachedEmojiFontResolved)
		{
			return cachedEmojiFontFamily;
		}

		cachedEmojiFontResolved = true;
		for (String candidate : EMOJI_FONT_CANDIDATES)
		{
			for (String family : AVAILABLE_FONT_FAMILIES)
			{
				if (family.equalsIgnoreCase(candidate))
				{
					cachedEmojiFontFamily = family;
					return cachedEmojiFontFamily;
				}
			}
		}

		cachedEmojiFontFamily = null;
		return null;
	}

	private void updateScrollFromPointer(String conversationKey, int desiredThumbY)
	{
		if (activeScrollbarTrackBounds == null || activeScrollbarThumbBounds == null)
		{
			return;
		}

		if (ModernMmoPmPlugin.FRIENDS_SCROLL_KEY.equals(conversationKey))
		{
			final int maxScroll = scrollMaxByConversation.getOrDefault(ModernMmoPmPlugin.FRIENDS_SCROLL_KEY, 0);
			if (maxScroll <= 0)
			{
				friendsListScrollOffset = 0;
				return;
			}

			final int thumbTravel = Math.max(1, activeScrollbarTrackBounds.height - activeScrollbarThumbBounds.height);
			final int clampedThumbY = Math.max(activeScrollbarTrackBounds.y, Math.min(desiredThumbY, activeScrollbarTrackBounds.y + thumbTravel));
			final float ratio = (clampedThumbY - activeScrollbarTrackBounds.y) / (float) thumbTravel;
			friendsListScrollOffset = Math.round(ratio * maxScroll);
			return;
		}

		final Conversation conversation = plugin.getConversation(conversationKey);
		if (conversation == null)
		{
			return;
		}

		final int maxScroll = scrollMaxByConversation.getOrDefault(conversationKey, 0);
		if (maxScroll <= 0)
		{
			conversation.setScrollOffset(0);
			return;
		}

		final int thumbTravel = Math.max(1, activeScrollbarTrackBounds.height - activeScrollbarThumbBounds.height);
		final int clampedThumbY = Math.max(activeScrollbarTrackBounds.y, Math.min(desiredThumbY, activeScrollbarTrackBounds.y + thumbTravel));
		final float ratio = (clampedThumbY - activeScrollbarTrackBounds.y) / (float) thumbTravel;
		conversation.setScrollOffset(Math.round((1.0f - ratio) * maxScroll));
	}

	private String resolveTabRevealTarget(List<Conversation> conversations)
	{
		final String activeKey = plugin.getActiveConversationKey();
		String revealKey = Objects.equals(lastActiveConversationKey, activeKey) ? null : activeKey;
		lastActiveConversationKey = activeKey;
		final Map<String, Long> nextFlashUntilByConversation = new HashMap<>();
		for (Conversation conversation : conversations)
		{
			final String key = conversation.getCleanedName();
			final long flashUntil = conversation.getFlashUntilMillis();
			nextFlashUntilByConversation.put(key, flashUntil);
			final long previousFlashUntil = lastFlashUntilByConversation.getOrDefault(key, 0L);
			if (flashUntil > previousFlashUntil && conversation.getUnreadCount() > 0)
			{
				revealKey = key;
			}
		}
		lastFlashUntilByConversation.clear();
		lastFlashUntilByConversation.putAll(nextFlashUntilByConversation);
		return revealKey;
	}

	private int ensureTabVisible(List<Conversation> conversations, String conversationKey, boolean horizontal, int currentOffset, int viewportSpan, int maxScroll)
	{
		if (conversationKey == null || viewportSpan <= 0)
		{
			return clampTabScroll(currentOffset, maxScroll);
		}

		final int convIndex = indexOfConversation(conversations, conversationKey);
		if (convIndex < 0)
		{
			return clampTabScroll(currentOffset, maxScroll);
		}
		final int index = convIndex;

		final int itemSpan = horizontal ? TAB_SIZE + TAB_GAP : TAB_HEIGHT + TAB_GAP;
		final int itemSize = horizontal ? TAB_SIZE : TAB_HEIGHT;
		final int itemStart = index * itemSpan;
		final int itemEnd = itemStart + itemSize;
		int nextOffset = currentOffset;
		if (itemStart < currentOffset)
		{
			nextOffset = itemStart;
		}
		else if (itemEnd > currentOffset + viewportSpan)
		{
			nextOffset = itemEnd - viewportSpan;
		}
		return clampTabScroll(nextOffset, maxScroll);
	}

	private static int indexOfConversation(List<Conversation> conversations, String conversationKey)
	{
		for (int i = 0; i < conversations.size(); i++)
		{
			if (conversationKey.equals(conversations.get(i).getCleanedName()))
			{
				return i;
			}
		}
		return -1;
	}

	private int getTabScrollOffset(boolean horizontal)
	{
		return horizontal ? horizontalTabScrollOffset : verticalTabScrollOffset;
	}

	private void setTabScrollOffset(boolean horizontal, int offset)
	{
