	private static String trimToWidth(FontMetrics fm, String text, int maxWidth)
	{
		if (fm.stringWidth(text) <= maxWidth)
		{
			return text;
		}

		String ellipsis = "...";
		String out = text;
		while (!out.isEmpty() && fm.stringWidth(out + ellipsis) > maxWidth)
		{
			out = out.substring(0, out.length() - 1);
		}
		return out + ellipsis;
	}

	private static Color applyAlpha(Color color, int alpha)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.max(0, Math.min(255, alpha)));
	}

	private static Color shade(Color color, float factor, int alpha)
	{
		return new Color(
			clamp(Math.round(color.getRed() * factor)),
			clamp(Math.round(color.getGreen() * factor)),
			clamp(Math.round(color.getBlue() * factor)),
			Math.max(0, Math.min(255, alpha)));
	}

	private static int clamp(int value)
	{
		return Math.max(0, Math.min(255, value));
	}

	private static int clampDimension(int value, int min, int max)
	{
		return Math.max(min, Math.min(max, value));
	}

