	private void drawStar(Graphics2D graphics, int centerX, int centerY, int outerRadius, int innerRadius, Color fill, Color border)
	{
		final int points = 10;
		final int[] xPoints = new int[points];
		final int[] yPoints = new int[points];
		for (int i = 0; i < points; i++)
		{
			final double angle = (-Math.PI / 2.0) + (i * Math.PI / 5.0);
			final int radius = (i & 1) == 0 ? outerRadius : innerRadius;
			xPoints[i] = centerX + (int) Math.round(Math.cos(angle) * radius);
			yPoints[i] = centerY + (int) Math.round(Math.sin(angle) * radius);
		}

		graphics.setColor(fill);
		graphics.fillPolygon(xPoints, yPoints, points);
		graphics.setColor(border);
		graphics.drawPolygon(xPoints, yPoints, points);
	}

	private void drawWorldRegionFlag(Graphics2D graphics, WorldRegion region, int x, int baselineY)
	{
		if (region == null)
		{
			return;
		}

		final int y = baselineY - FRIEND_REGION_FLAG_HEIGHT + 1;
		switch (region)
		{
			case US:
			case US_EAST:
			case US_WEST:
				drawUsFlag(graphics, x, y);
				break;
			case GB:
				drawGbFlag(graphics, x, y);
				break;
			case AU:
				drawAuFlag(graphics, x, y);
				break;
			case DE:
				drawDeFlag(graphics, x, y);
				break;
			case BR:
				drawBrFlag(graphics, x, y);
				break;
			default:
				break;
		}

		graphics.setColor(new Color(12, 14, 18, 180));
		graphics.drawRect(x, y, FRIEND_REGION_FLAG_WIDTH, FRIEND_REGION_FLAG_HEIGHT);
	}

