	private static boolean intersectsVertically(Rectangle a, Rectangle b)
	{
		return a.y < b.y + b.height && a.y + a.height > b.y;
	}

	private Rectangle positionMinimizeButton(Rectangle anchorRect)
	{
		final int inset = 4;
		final int leftX = anchorRect.x + inset;
		final int rightX = anchorRect.x + Math.max(inset, anchorRect.width - ICON_BUTTON_SIZE - inset);
		final int centeredY = anchorRect.y + Math.max(1, (anchorRect.height - ICON_BUTTON_SIZE) / 2);
		final boolean compactBar = anchorRect.height <= ACTION_BAR_HEIGHT;
		final int topY = compactBar
			? centeredY
			: anchorRect.y + Math.min(inset, Math.max(1, anchorRect.height - ICON_BUTTON_SIZE));
		final int bottomY = compactBar
			? centeredY
			: anchorRect.y + Math.max(1, anchorRect.height - ICON_BUTTON_SIZE - inset);
		switch (plugin.getConfig().minimizeButtonLocation())
		{
			case TOP_RIGHT:
				return new Rectangle(rightX, topY, ICON_BUTTON_SIZE, ICON_BUTTON_SIZE);
			case BOTTOM_RIGHT:
				return new Rectangle(rightX, bottomY, ICON_BUTTON_SIZE, ICON_BUTTON_SIZE);
			case BOTTOM_LEFT:
				return new Rectangle(leftX, bottomY, ICON_BUTTON_SIZE, ICON_BUTTON_SIZE);
			case TOP_LEFT:
			default:
				return new Rectangle(leftX, topY, ICON_BUTTON_SIZE, ICON_BUTTON_SIZE);
		}
	}

	private Rectangle positionFooterMinimizeButton(Rectangle footerRect)
	{
		final int inset = 4;
		final int y = footerButtonY(footerRect);
		switch (plugin.getConfig().minimizeButtonLocation())
		{
			case BOTTOM_RIGHT:
				return new Rectangle(footerRect.x + footerRect.width - ICON_BUTTON_SIZE - inset, y, ICON_BUTTON_SIZE, ICON_BUTTON_SIZE);
			case BOTTOM_LEFT:
			default:
				return new Rectangle(footerRect.x + inset, y, ICON_BUTTON_SIZE, ICON_BUTTON_SIZE);
		}
	}

	private static int footerButtonY(Rectangle footerRect)
	{
		return footerRect.y + Math.max(1, (footerRect.height - ICON_BUTTON_SIZE) / 2);
	}

