		graphics.setColor(hovered ? new Color(34, 112, 56, 242) : new Color(14, 18, 26, 236));
		graphics.fillRoundRect(rect.x, rect.y, rect.width, rect.height, 5, 5);
		graphics.setColor(hovered ? new Color(118, 224, 142, 248) : new Color(170, 184, 222, 244));
		graphics.drawRoundRect(rect.x, rect.y, rect.width, rect.height, 5, 5);
		drawMailGlyph(graphics, rect);
	}

	private static void drawMailGlyph(Graphics2D graphics, Rectangle rect)
	{
		final int left = rect.x + Math.max(3, (rect.width - 10) / 2);
		final int top = rect.y + Math.max(4, (rect.height - 8) / 2);
		final int right = left + 10;
		final int bottom = top + 8;
		final int midX = left + 5;
		final int foldY = top + 5;

		graphics.setColor(HEADER_TEXT);
		graphics.drawRect(left, top, 10, 7);
		graphics.drawLine(left + 1, top + 1, midX, foldY);
		graphics.drawLine(right - 1, top + 1, midX, foldY);
		graphics.drawLine(left + 1, bottom - 1, midX - 1, foldY - 1);
		graphics.drawLine(right - 1, bottom - 1, midX + 1, foldY - 1);
	}

	private void drawCloseGlyph(Graphics2D graphics, Rectangle rect, boolean hovered)
	{
		graphics.setColor(hovered ? new Color(130, 44, 44, 210) : new Color(24, 26, 32, 150));
		graphics.fillRoundRect(rect.x, rect.y, rect.width, rect.height, 5, 5);
		graphics.setColor(hovered ? new Color(210, 90, 90, 220) : PANEL_BORDER);
		graphics.drawRoundRect(rect.x, rect.y, rect.width, rect.height, 5, 5);
		graphics.setColor(HEADER_TEXT);
		graphics.drawLine(rect.x + 3, rect.y + 3, rect.x + rect.width - 4, rect.y + rect.height - 4);
		graphics.drawLine(rect.x + rect.width - 4, rect.y + 3, rect.x + 3, rect.y + rect.height - 4);
	}

	private void drawText(Graphics2D graphics, String text, int x, int y, Color color)
	{
		if (plugin.getConfig().textOutline())
		{
			graphics.setColor(Color.BLACK);
			graphics.drawString(text, x - 1, y);
			graphics.drawString(text, x + 1, y);
			graphics.drawString(text, x, y - 1);
			graphics.drawString(text, x, y + 1);
			graphics.drawString(text, x - 1, y - 1);
			graphics.drawString(text, x + 1, y - 1);
			graphics.drawString(text, x - 1, y + 1);
			graphics.drawString(text, x + 1, y + 1);
		}
		graphics.setColor(color);
		graphics.drawString(text, x, y);
	}
}

package com.modernmmopm.util;

import java.awt.Color;
import java.awt.FontMetrics;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;

public final class PmMessageFormatter
{
	private static final Color NAMED_HIGHLIGHT_COLOR = new Color(0xFFFF00);

	private PmMessageFormatter()
	{
	}

	public static List<StyledRun> parseRuns(String raw, Color defaultColor)
	{
		if (raw == null || raw.isEmpty())
		{
			return Collections.emptyList();
		}

		final String stripped = stripVariationSelectors(raw);
		final List<StyledRun> runs = new ArrayList<>();
		final Deque<Color> colorStack = new ArrayDeque<>();
		Color currentColor = defaultColor;
		StringBuilder text = new StringBuilder();

		for (int i = 0; i < stripped.length(); i++)
		{
			final char ch = stripped.charAt(i);
			if (ch != '<')
			{
				text.append(ch);
				continue;
			}

			final int closing = stripped.indexOf('>', i);
			if (closing < 0)
			{
				text.append(ch);
				continue;
			}

			final String tag = stripped.substring(i + 1, closing).trim();
			final String lowerTag = tag.toLowerCase();
			final boolean isLineBreak = "br".equals(lowerTag) || "br/".equals(lowerTag) || "br /".equals(lowerTag);
			if ("lt".equals(lowerTag))
			{
				text.append('<');
				i = closing;
				continue;
			}
			if ("gt".equals(lowerTag))
			{
				text.append('>');
				i = closing;
				continue;
			}
			if (isLineBreak)
			{
				flushRun(runs, text, currentColor);
				text.append('\n');
				flushRun(runs, text, currentColor);
				i = closing;
				continue;
			}

			if (lowerTag.startsWith("img="))
			{
				final int iconId = parseImageId(tag.substring(4));
				if (iconId >= 0)
				{
					flushRun(runs, text, currentColor);
					runs.add(StyledRun.chatIcon(stripped.substring(i, closing + 1), currentColor, iconId));
					i = closing;
					continue;
				}
			}

			if (lowerTag.startsWith("col="))
			{
				final Color parsedColor = parseColor(tag.substring(4));
				if (parsedColor != null)
				{
					flushRun(runs, text, currentColor);
					colorStack.push(currentColor);
					currentColor = parsedColor;
					i = closing;
					continue;
				}
			}
			else if (lowerTag.startsWith("col"))
			{
				final Color namedColor = parseNamedColor(tag.substring(3), defaultColor);
				if (namedColor != null)
				{
					flushRun(runs, text, currentColor);
					currentColor = namedColor;
					i = closing;
					continue;
				}
			}
			else if ("/col".equals(lowerTag))
			{
				flushRun(runs, text, currentColor);
				currentColor = colorStack.isEmpty() ? defaultColor : colorStack.pop();
				i = closing;
				continue;
			}

			text.append(stripped, i, closing + 1);
			i = closing;
		}

		flushRun(runs, text, currentColor);
		return runs;
	}

	public static List<StyledLine> wrapRuns(FontMetrics textMetrics, FontMetrics emojiMetrics, List<StyledRun> runs, int maxWidth)
	{
		if (runs.isEmpty())
		{
			return Collections.singletonList(new StyledLine(Collections.singletonList(new StyledRun("", Color.WHITE, false)), 0));
		}

		final FontMetrics resolvedEmojiMetrics = emojiMetrics != null ? emojiMetrics : textMetrics;
		final int chatIconWidth = chatIconWidth(textMetrics);
		final List<StyledToken> tokens = tokenize(runs);
		final List<StyledLine> lines = new ArrayList<>();
		final LineBuilder lineBuilder = new LineBuilder();
		final int safeMaxWidth = Math.max(1, maxWidth);

		for (StyledToken token : tokens)
		{
			if (token.newline)
			{
				lines.add(lineBuilder.build());
				lineBuilder.clear();
				continue;
			}

			final int tokenWidth = tokenWidth(token, textMetrics, resolvedEmojiMetrics, chatIconWidth);
			if (token.whitespace)
			{
				if (lineBuilder.isEmpty())
				{
					continue;
				}
				if (lineBuilder.width + tokenWidth <= safeMaxWidth)
				{
					lineBuilder.append(token.text, token.color, token.emoji, token.chatIconId, tokenWidth);
				}
				else
				{
					lines.add(lineBuilder.build());
					lineBuilder.clear();
				}
				continue;
			}

			if (lineBuilder.isEmpty())
			{
				appendOrSplitToken(lines, lineBuilder, token, textMetrics, resolvedEmojiMetrics, safeMaxWidth);
				continue;
			}

			if (lineBuilder.width + tokenWidth <= safeMaxWidth)
			{
				lineBuilder.append(token.text, token.color, token.emoji, token.chatIconId, tokenWidth);
				continue;
			}

			lines.add(lineBuilder.build());
			lineBuilder.clear();
			appendOrSplitToken(lines, lineBuilder, token, textMetrics, resolvedEmojiMetrics, safeMaxWidth);
		}

		if (!lineBuilder.isEmpty() || lines.isEmpty())
		{
			lines.add(lineBuilder.build());
		}

		return lines;
	}

	public static String visibleText(String raw)
	{
		final List<StyledRun> runs = parseRuns(raw, Color.WHITE);
		if (runs.isEmpty())
		{
			return "";
		}

		StringBuilder out = new StringBuilder();
		for (StyledRun run : runs)
		{
			out.append(run.text);
		}

		return out.toString()
			.replace('\r', ' ')
			.replace('\n', ' ')
			.trim()
			.replaceAll("\\s+", " ");
	}

	public static boolean isEmojiCodepoint(int codePoint)
	{
		return codePoint >= 0x1F000
			|| (codePoint >= 0x2600 && codePoint <= 0x27BF);
	}

	private static String stripVariationSelectors(String text)
	{
		if (text == null || text.isEmpty())
		{
			return text;
		}

		StringBuilder out = null;
		for (int i = 0; i < text.length(); i++)
		{
			final char ch = text.charAt(i);
			if (ch == '\uFE0F' || ch == '\uFE0E')
			{
				if (out == null)
				{
					out = new StringBuilder(text.length());
					out.append(text, 0, i);
				}
				continue;
			}
			if (out != null)
			{
				out.append(ch);
			}
		}
		return out == null ? text : out.toString();
	}

	private static void appendOrSplitToken(List<StyledLine> lines, LineBuilder lineBuilder, StyledToken token,
		FontMetrics textMetrics, FontMetrics emojiMetrics, int maxWidth)
	{
		if (token.isChatIcon())
		{
			lineBuilder.append(token.text, token.color, false, token.chatIconId, chatIconWidth(textMetrics));
			return;
		}

		final FontMetrics tokenMetrics = token.emoji ? emojiMetrics : textMetrics;
		final int tokenWidth = tokenMetrics.stringWidth(token.text);
		if (tokenWidth <= maxWidth)
		{
			lineBuilder.append(token.text, token.color, token.emoji, token.chatIconId, tokenWidth);
			return;
		}

		StringBuilder chunk = new StringBuilder();
		int chunkWidth = 0;
		int index = 0;
		while (index < token.text.length())
		{
			final int codePoint = token.text.codePointAt(index);
			final int charCount = Character.charCount(codePoint);
			final String glyph = token.text.substring(index, index + charCount);
			final int glyphWidth = tokenMetrics.stringWidth(glyph);
			if (chunkWidth > 0 && chunkWidth + glyphWidth > maxWidth)
			{
				lineBuilder.append(chunk.toString(), token.color, token.emoji, token.chatIconId, chunkWidth);
				lines.add(lineBuilder.build());
				lineBuilder.clear();
				chunk.setLength(0);
				chunkWidth = 0;
			}

			chunk.append(glyph);
			chunkWidth += glyphWidth;
			index += charCount;
		}

		if (chunkWidth > 0)
		{
			lineBuilder.append(chunk.toString(), token.color, token.emoji, token.chatIconId, chunkWidth);
		}
	}

	private static List<StyledToken> tokenize(List<StyledRun> runs)
	{
		final List<StyledToken> tokens = new ArrayList<>();
		for (StyledRun run : runs)
		{
			if (run.isChatIcon())
			{
				tokens.add(new StyledToken(run.text, run.color, false, false, false, run.chatIconId));
				continue;
			}

			final String text = run.text;
			int index = 0;
			while (index < text.length())
			{
				final int codePoint = text.codePointAt(index);
				final int charCount = Character.charCount(codePoint);
				if (codePoint == '\n')
				{
					tokens.add(StyledToken.newline());
					index += charCount;
					continue;
				}

				final boolean whitespace = Character.isWhitespace(codePoint);
				final boolean emoji = isEmojiCodepoint(codePoint);
				final int start = index;
				index += charCount;
				while (index < text.length())
				{
					final int nextCp = text.codePointAt(index);
					if (nextCp == '\n'
						|| Character.isWhitespace(nextCp) != whitespace
						|| isEmojiCodepoint(nextCp) != emoji)
					{
						break;
					}
					index += Character.charCount(nextCp);
				}

				tokens.add(new StyledToken(text.substring(start, index), run.color, whitespace, false, emoji, -1));
			}
		}
		return tokens;
	}

	private static void flushRun(List<StyledRun> runs, StringBuilder text, Color color)
	{
		if (text.length() == 0)
		{
			return;
		}

		final String value = text.toString();
		if (!runs.isEmpty())
		{
			final StyledRun previous = runs.get(runs.size() - 1);
			if (previous.color.equals(color) && !previous.emoji && !previous.isChatIcon())
			{
				runs.set(runs.size() - 1, new StyledRun(previous.text + value, color, false));
				text.setLength(0);
				return;
			}
		}

		runs.add(new StyledRun(value, color, false));
		text.setLength(0);
	}

	private static int chatIconWidth(FontMetrics textMetrics)
	{
		return Math.max(1, textMetrics.getHeight());
	}

	private static int tokenWidth(StyledToken token, FontMetrics textMetrics, FontMetrics emojiMetrics, int chatIconWidth)
	{
		if (token.isChatIcon())
		{
			return chatIconWidth;
		}

		return (token.emoji ? emojiMetrics : textMetrics).stringWidth(token.text);
	}

	private static int parseImageId(String raw)
	{
		try
		{
			final int iconId = Integer.parseInt(raw.trim());
			return iconId >= 0 ? iconId : -1;
		}
		catch (NumberFormatException ex)
		{
			return -1;
		}
	}

	private static Color parseNamedColor(String raw, Color defaultColor)
	{
		if ("normal".equalsIgnoreCase(raw))
		{
			return defaultColor;
		}
		if ("highlight".equalsIgnoreCase(raw))
		{
			return NAMED_HIGHLIGHT_COLOR;
		}
		return null;
	}

	private static Color parseColor(String raw)
	{
		String value = raw == null ? "" : raw.trim();
		if (value.startsWith("#"))
		{
			value = value.substring(1);
		}

		if (value.length() != 6)
		{
			return null;
		}

		try
		{
			return new Color(Integer.parseInt(value, 16));
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}

	public static final class StyledRun
	{
		private final String text;
		private final Color color;
		private final boolean emoji;
		private final int chatIconId;

		public StyledRun(String text, Color color, boolean emoji)
		{
			this(text, color, emoji, -1);
		}

		private StyledRun(String text, Color color, boolean emoji, int chatIconId)
		{
			this.text = text;
			this.color = color;
			this.emoji = emoji;
			this.chatIconId = chatIconId;
		}

		private static StyledRun chatIcon(String text, Color color, int chatIconId)
		{
			return new StyledRun(text, color, false, chatIconId);
		}

		public String getText()
		{
			return text;
		}

		public Color getColor()
		{
			return color;
		}

		public boolean isEmoji()
		{
			return emoji;
		}

		public boolean isChatIcon()
		{
			return chatIconId >= 0;
		}

		public int getChatIconId()
		{
			return chatIconId;
		}
	}

	public static final class StyledLine
	{
		private final List<StyledRun> runs;
		private final int width;

		public StyledLine(List<StyledRun> runs, int width)
		{
			this.runs = Collections.unmodifiableList(new ArrayList<>(runs));
			this.width = width;
		}

		public List<StyledRun> getRuns()
		{
			return runs;
		}

		public int getWidth()
		{
			return width;
		}
	}

	private static final class StyledToken
	{
		private final String text;
		private final Color color;
		private final boolean whitespace;
		private final boolean newline;
		private final boolean emoji;
		private final int chatIconId;

		private StyledToken(String text, Color color, boolean whitespace, boolean newline, boolean emoji, int chatIconId)
		{
			this.text = text;
			this.color = color;
			this.whitespace = whitespace;
			this.newline = newline;
			this.emoji = emoji;
			this.chatIconId = chatIconId;
		}

		private static StyledToken newline()
		{
			return new StyledToken("", Color.WHITE, false, true, false, -1);
		}

		private boolean isChatIcon()
		{
			return chatIconId >= 0;
		}
	}

	private static final class LineBuilder
	{
		private final List<StyledRun> runs = new ArrayList<>();
		private int width;

		private boolean isEmpty()
		{
			return runs.isEmpty();
		}

		private void append(String text, Color color, boolean emoji, int chatIconId, int addedWidth)
		{
			if (text.isEmpty())
			{
				return;
			}

			if (!runs.isEmpty())
			{
				final StyledRun previous = runs.get(runs.size() - 1);
				if (!previous.isChatIcon() && chatIconId < 0 && previous.color.equals(color) && previous.emoji == emoji)
				{
					runs.set(runs.size() - 1, new StyledRun(previous.text + text, color, emoji));
					width += addedWidth;
					return;
				}
			}

			runs.add(new StyledRun(text, color, emoji, chatIconId));
			width += addedWidth;
		}

		private StyledLine build()
		{
			if (runs.isEmpty())
			{
				return new StyledLine(Collections.singletonList(new StyledRun("", Color.WHITE, false)), 0);
			}
			return new StyledLine(runs, width);
		}

		private void clear()
		{
			runs.clear();
			width = 0;
		}
	}
}

