	public static String replaceShortcodes(String text)
	{
		if (text == null || text.isEmpty())
		{
			return text == null ? "" : text;
		}

		StringBuilder out = new StringBuilder(text.length());
		StringBuilder plain = new StringBuilder(text.length());
		for (int index = 0; index < text.length(); index++)
		{
			final int tagEnd = markupEnd(text, index);
			if (tagEnd >= 0)
			{
				out.append(replacePlainSegment(plain.toString()));
				plain.setLength(0);
				out.append(text, index, tagEnd + 1);
				index = tagEnd;
				continue;
			}

			plain.append(text.charAt(index));
		}

		out.append(replacePlainSegment(plain.toString()));
		return out.toString();
	}

	private static String replacePlainSegment(String segment)
	{
		final String decoded = segment
			.replace("<lt>", "<")
			.replace("<LT>", "<")
			.replace("<gt>", ">")
			.replace("<GT>", ">");
		if (decoded.isEmpty())
		{
			return decoded;
		}

		final StringBuilder out = new StringBuilder(decoded.length());
		for (int index = 0; index < decoded.length(); )
		{
			String matchedShortcode = null;
			for (String shortcode : SHORTCODES)
			{
				if (decoded.regionMatches(index, shortcode, 0, shortcode.length())
					&& hasBoundaryBefore(decoded, index)
					&& hasBoundaryAfter(decoded, index + shortcode.length()))
				{
					matchedShortcode = shortcode;
					break;
				}
			}

			if (matchedShortcode != null)
			{
				out.append(EMOJI_REPLACEMENTS.get(matchedShortcode));
				index += matchedShortcode.length();
				continue;
			}

			out.append(decoded.charAt(index));
			index++;
		}
		return out.toString();
	}

	private static String unicode(int codePoint)
	{
		return new String(Character.toChars(codePoint));
	}

	private static boolean hasBoundaryBefore(String text, int index)
	{
		return index <= 0 || isBoundaryChar(text.charAt(index - 1));
	}

	private static boolean hasBoundaryAfter(String text, int index)
	{
		return index >= text.length() || isBoundaryChar(text.charAt(index));
	}

	private static boolean isBoundaryChar(char ch)
	{
		return Character.isWhitespace(ch)
			|| ch == '"'
			|| ch == '\''
			|| ch == ','
			|| ch == '.'
			|| ch == '!'
			|| ch == '?'
			|| ch == ';';
	}

	private static int markupEnd(String text, int index)
	{
		if (text.charAt(index) != '<')
		{
			return -1;
		}

		if (text.regionMatches(true, index, "<col=", 0, 5))
		{
			return text.indexOf('>', index);
		}

		if (text.regionMatches(true, index, "</col>", 0, 6))
		{
			return index + 5;
		}

		if (text.regionMatches(true, index, "<br>", 0, 4))
		{
			return index + 3;
		}

		if (text.regionMatches(true, index, "<br/>", 0, 5))
		{
			return index + 4;
		}

		if (text.regionMatches(true, index, "<br />", 0, 6))
		{
			return index + 5;
		}

		return -1;
	}
}

package com.modernmmopm.util;

import net.runelite.client.util.Text;

public final class NameSanitizer
{
	private NameSanitizer()
	{
	}

	public static String cleanedKey(String rawName)
	{
		if (rawName == null)
		{
			return "";
		}

		return Text.standardize(Text.removeTags(rawName)).trim();
	}

	public static String displayName(String rawName)
	{
		if (rawName == null)
		{
			return "";
		}

		return Text.removeTags(rawName).trim();
	}
}
